b=read('DB_BEFORE.json');E=read('EXTRA_BEFORE.json');old=json.loads(b['root']['canonical_preimage']);root=b['root']['revision_sha256'];edge=read('EDGE_BEFORE.json');D=read('SQL_DELTA.json');N=read('NEW_OBJECTS.json');policy=read('ROOT_CONFIG_DELTA.json')
assert root=='ac7208e3443f5ecfdec0c5ae6e146c467726080aae70efa53ebc06b9e18d5c65' and sha(b['root']['canonical_preimage'])==root
assert edge['version']==96 and edge['status']=='ACTIVE' and len(edge['files'])==14 and edge['ezbr_sha256']==old['edge_bundles'][0]['ezbr_sha256']
