 if sig not in attrs:attrs[sig]={k:v for k,v in h.items()if k not in ['oid','ddl_md5']};sources[sig]=ref('baseline/'+sig.split('(')[0].replace('.','__')+'.sql')
edge_ready=json.loads((P.parent/'edge_author/EDGE_READY.json').read_text());consumer=json.loads((P.parent/'edge_author/CLIENT_READY.json').read_text())
assert edge_ready['ready']is True and edge_ready['baseline_version']==96 and len(edge_ready['files'])==14
assert consumer['ready']is True and consumer['unchanged']is True
expected_edge=[]
for f in edge_ready['files']:
 p=Path(f['path']);assert sha(p.read_bytes())==f['sha256'] and p.stat().st_size==f['bytes'];expected_edge.append({k:f[k]for k in ['name','bytes','sha256']})
for f in consumer['files']:assert f['sha256']==old['ui']['files'][f['name']]['sha256'] and f['bytes']==old['ui']['files'][f['name']]['bytes']
recipe={'schema_version':'c1266-native-intent-legal-actions-integrated-recipe/1','baseline_root':root,'builder':ref('BUILD_INTEGRATED.py'),'postflight_checker':ref('POSTFLIGHT_CHECK.py'),'baseline_query':ref('BASELINE.sql'),'extra_query':ref('EXTRA.sql'),'baseline_db':ref('DB_BEFORE.json'),'baseline_scene':ref('EXTRA_BEFORE.json'),'baseline_edge':ref('EDGE_BEFORE.json'),'author':ref('AUTHOR.json'),'author_static':ref('AUTHOR_STATIC.json'),'author_contract':ref('CONTRACT.json'),'new_objects':ref('NEW_OBJECTS.json'),'sources':sources,'expected_attributes':attrs,'Root_policy':policy,'matrix':ref('MATRIX.json'),'saved_writer':ref('SAVED_WRITER_BINDING.json'),'DB_generators':{n:ref(n)for n in ['DB_BUILD_DELTA.py','DB_BUILD_HELPERS.py','DB_STATIC.py','DB_NATIVE_ENTRY_BODY.sql']},'Edge_author':ref('../edge_author/AUTHOR.json'),'Edge_ready':ref('../edge_author/EDGE_READY.json'),'Edge_static':ref('../edge_author/STATIC.json'),'Edge_builder':ref('../edge_author/BUILD_CANDIDATE.py'),'Edge_static_script':ref('../edge_author/STATIC.py'),'UI_unchanged':ref('../edge_author/CLIENT_READY.json'),'expected_edge_files':expected_edge,'existing_bodies_changed':9,'new_helpers':4,'new_tables':0,'Edge_files_changed':1,'UI_files_changed':0,'provider_calls':0,'operation':'Existing publisher transaction realizes hostile narrative intentions as approved native attack, native movement plus separate main Passa, or unresolved attempt plus native Passa. No source, payload or old Fato rewrite; exact saved82d uses retained raw, zero additional AI. All receipts sealed to one Fato; ordinary native round/defense/closure rules remain authoritative.','preserved':['all10Fati20roles48protectedfields','all works/results/receipts/quotas/audit/source/cursor/raw-output hashes before runtime','all other Root config/policies; tokens/global/day/shared/USD hard total0.50 and backing0.3136','UI exact published finisher unchanged','historical counters and review history'],'guard':'fresh exact full baseline+scene+161headers+5existing external headers;9delta bodies and4new service-only helpers; oldOID/ACL preserved; zero inflight before/after; exact Edge97 observed after source review before SQL bind; no apply/provider by author','runtime':'NOT_RUN','history':'same request cumulative deroga5 preserved; no counter reset'}
