for f in N['functions']:s+=guard('to_regprocedure('+q(f['signature'])+') IS NULL','NATIVE_INTENT_NEW_HELPER_ABSENT')+' EXECUTE '+q((P/f['path']).read_text())+';\n'
for d in D:s+=' EXECUTE '+q((P/d['path']).read_text())+';\n'
