    ||!['type','anyOf','$ref','properties','enum'].some(k=>Object.hasOwn(cursor,k)))return null;
  return path.slice();
}
function countSchemaDiagnosticMessage3(error,payload,status){
  const out={schemaReason:null,schemaContext:null};
