  const wire=single(schema?.properties?.schema_version);
  const idWire=typeof wire==='string'&&wire.length==='mission-director-literal-ids/1:'.length+36&&/^mission-director-literal-ids\/[12]:[a-fA-F0-9]{8}(?:-[a-fA-F0-9]{4}){3}-[a-fA-F0-9]{12}$/.test(wire);
  const numericWire=typeof wire==='string'&&/^(?:mission-director-numeric-catalog\/1|mission-director-peer-confirmation\/[12]):[a-fA-F0-9]{8}(?:-[a-fA-F0-9]{4}){3}-[a-fA-F0-9]{12}$/.test(wire);
  if(!record(schema)||schema.type!=='object'||schema.additionalProperties!==false||!record(schema.properties)
    ||!Array.isArray(schema.required)||!schema.required.includes('role_interpretation')
    ||(!['mission-director-proposal/4','mission-director-joint-witness/1'].includes(single(schema.properties.schema_version))&&!idWire&&!numericWire))return false;
  if(idWire&&Object.keys(schema.properties.schema_version).length!==2)return false;
  if(numericWire){
    const closed=(n,keys)=>record(n)&&n.type==='object'&&n.additionalProperties===false&&record(n.properties)&&Object.keys(n.properties).length===keys.length&&keys.every(k=>Object.hasOwn(n.properties,k))&&Array.isArray(n.required)&&n.required.length===keys.length&&keys.every(k=>n.required.includes(k));
    const globals=['schema_version','source_window_id','source_evidence','selection','world_reaction_intent','profile_audit','progression','role_interpretation'];
    if(!closed(schema,globals)||Object.keys(schema.properties.schema_version).length!==2||!uuid(single(schema.properties.source_window_id)))return false;
    const role=schema.properties.role_interpretation,choice=schema.properties.selection,progress=schema.properties.progression;
    if(!closed(role,['p0','p1'])||!record(choice)||!Array.isArray(choice.anyOf)||!choice.anyOf.length
      ||choice.anyOf.some(c=>!closed(c,['v','b','n']))
      ||!record(progress)||!Array.isArray(progress.anyOf)||!progress.anyOf.length
      ||progress.anyOf.some(c=>!closed(c,['i','m'])))return false;
    for(const name of ['p0','p1']){
      const row=role.properties[name];if(!record(row)||!Array.isArray(row.anyOf)||row.anyOf.length!==9)return false;
      for(let n=0;n<9;n++){const variant=row.anyOf[n],keys=Array.from({length:n},(_,i)=>'d'+i);if(!closed(variant,['u'+n,...keys]))return false;const gaps=variant.properties['u'+n];if(!record(gaps)||gaps.type!=='array'||gaps.minItems!==(n?0:1)||gaps.maxItems!==8-n)return false;const peer2=wire.startsWith('mission-director-peer-confirmation/2:');if(peer2?(!closed(gaps.items,['g','q'])||gaps.items.properties.g?.type!=='integer'||gaps.items.properties.g.minimum!==0||gaps.items.properties.g.maximum!==n||!record(gaps.items.properties.q)):(gaps.items?.type!=='integer'||gaps.items.minimum!==0||gaps.items.maximum!==n))return false;}
    }
    const defs=schema.$defs;if(!record(defs)||Object.keys(defs).length<1||Object.keys(defs).length>1000)return false;
    return Object.keys(defs).every(name=>/^n[0-9]{1,3}$/.test(name)&&record(defs[name]));
  }
  if(idWire&&wire.startsWith('mission-director-literal-ids/2:')){
    const choice=schema.properties.selection,g=schema.properties.progression;
    const keys=['current_intent','movement_role_ids','guidance_fato_id','guidance_quote'];
    if(Object.hasOwn(schema.properties,'opportunity_id')||Object.hasOwn(schema.properties,'action_kind')
      ||!schema.required.includes('selection')||!record(choice)||!Array.isArray(choice.anyOf)||choice.anyOf.length<1
      ||!record(g)||g.type!=='object'||g.additionalProperties!==false||!record(g.properties)
      ||Object.keys(g.properties).length!==keys.length||!keys.every(k=>Object.hasOwn(g.properties,k))
      ||!Array.isArray(g.required)||g.required.length!==keys.length||!keys.every(k=>g.required.includes(k)))return false;
    if(choice.anyOf.some(c=>!record(c)||c.type!=='object'||c.additionalProperties!==false||!record(c.properties)
      ||Object.keys(c.properties).length!==3||!['opportunity_id','action_kind','basis'].every(k=>Object.hasOwn(c.properties,k))
      ||!Array.isArray(c.required)||c.required.length!==3||!['opportunity_id','action_kind','basis'].every(k=>c.required.includes(k))))return false;
