        &&proof.schema_version==='c1266-campaign-gen-no-http/1'&&proof.work_id===work.work_id
        &&proof.dispatch_id===dispatch.dispatch_id&&uuid(proof.receipt_id)&&uuid(proof.call_id)
        &&uuid(proof.campaign_id)&&sha(proof.campaign_policy_sha256)
