 if sig not in root_sigs:
  for key in ['c1266_functions','all_function_headers']:s+=' newpre:=jsonb_set(newpre,'+q('{db_core,'+key+'}')+',(newpre#>'+q('{db_core,'+key+'}')+")||jsonb_build_array(heads));\n"
 s+=" expected:=jsonb_set(expected,'{headers}',(SELECT jsonb_agg(x ORDER BY x->>'signature') FROM (SELECT CASE WHEN h->>'signature'="+q(sig)+" THEN heads ELSE h END x FROM jsonb_array_elements(expected->'headers') h"+(" UNION ALL SELECT heads"if sig not in root_sigs else '')+" ) z));\n"
 if sig in extras:s+=" expected:=jsonb_set(expected,'{legal_dependencies}',(SELECT jsonb_agg(CASE WHEN h->>'signature'="+q(sig)+" THEN heads ELSE h END ORDER BY h->>'signature') FROM jsonb_array_elements(expected->'legal_dependencies') h));\n"
s+=" root_text:=newpre::text;\n"+guard('octet_length(root_text)<=262144','NATIVE_INTENT_ROOT_SIZE')+" root_sha:=encode(extensions.digest(convert_to(root_text,'UTF8'),'sha256'),'hex');\n"
s+=" UPDATE mission_factory_owner.editor_release_readiness SET canonical_preimage=root_text,revision_sha256=root_sha,observed_revision_sha256=root_sha,client_build='mission-factory-admin/2:'||root_sha,updated_at=clock_timestamp() WHERE singleton AND revision_sha256="+q(root)+';\n GET DIAGNOSTICS n=ROW_COUNT;\n'+guard('n=1','NATIVE_INTENT_ROOT_CAS')
s+=' UPDATE mission_factory_owner.c464_control SET release_sha256=root_sha WHERE singleton;\n GET DIAGNOSTICS n=ROW_COUNT;\n'+guard('n=1','NATIVE_INTENT_G2_CAS')
s+=' UPDATE mission_factory_owner.provider_authoring_admissions SET release_sha256=root_sha WHERE actor_user IN('+','.join(q(a['actor_user'])for a in b['admissions'])+');\n GET DIAGNOSTICS n=ROW_COUNT;\n'+guard('n='+str(len(b['admissions'])),'NATIVE_INTENT_ADMISSIONS_CAS')
for path,expr in [('{root,canonical_preimage}','to_jsonb(root_text)'),('{root,revision_sha256}','to_jsonb(root_sha)'),('{root,observed_revision_sha256}','to_jsonb(root_sha)'),('{root,client_build}',"to_jsonb('mission-factory-admin/2:'||root_sha)"),('{g2,release_sha256}','to_jsonb(root_sha)')]:s+=' expected:=jsonb_set(expected,'+q(path)+','+expr+');\n'
for i in range(len(b['admissions'])):s+=' expected:=jsonb_set(expected,'+q('{admissions,'+str(i)+',release_sha256}')+',to_jsonb(root_sha));\n'
s+=' EXECUTE '+q(query)+' INTO actual;\n'+guard("((actual-'captured_at') #- '{root,updated_at}')=(expected #- '{root,updated_at}')",'NATIVE_INTENT_ONLY_METADATA_DIFF')+' EXECUTE '+q(extra)+' INTO after_extra;\n'+guard('after_extra=before_extra','NATIVE_INTENT_SCENE_KEEP')+guard(inflight,'NATIVE_INTENT_ACTIVE_AFTER')+"END $usd_install$;NOTIFY pgrst,'reload schema';COMMIT;\n"
(P/'INSTALL.sql').write_text(s);save('BOUND_MANIFEST.json',{'recipe':ref('RECIPE.json'),'builder':ref('BUILD_INTEGRATED.py'),'review':ref('INTEGRATED_REVIEW.json'),'installer':ref('INSTALL.sql'),'existing_bodies_changed':0,'existing_configuration_changes':2,'new_helpers':0,'Edge_UI_changed':0,'provider_calls':0});print(canon({'installer':ref('INSTALL.sql'),'status':'BOUND_AWAITING_MATERIAL_REVIEW'}))

