import json,hashlib,sys
P=Path(__file__).parent
r=lambda n:json.loads((P/n).read_text());sha=lambda n:hashlib.sha256((P/n).read_bytes()).hexdigest()
b=r('DB_BEFORE.json');a=r('DB_AFTER.json');e=r('EXTRA_BEFORE.json');f=r('EXTRA_AFTER.json');D=r('SQL_DELTA.json');N=r('NEW_OBJECTS.json');old=json.loads(b['root']['canonical_preimage']);new=json.loads(a['root']['canonical_preimage']);expected=r('EXPECTED_ROOT.json');checks={}
checks['all_gameplay_history_rows_exact']=e==f
checks['zero_active_and10Fati20roles48fields']=f['active_work_count']==0 and len(f['fati'])==10 and len(f['roles'])==20 and a['protected']==b['protected'] and a['protected']['protected_field_count']==48
checks['economic_backing_and_all_ledger_exact']=a['dispatch_admission']==b['dispatch_admission'] and a['dispatch_admission']['cost_budget_usd']==0.3136 and f['quota']==e['quota'] and f['dispatch_receipts']==e['dispatch_receipts']
before={h['signature']:h for h in b['headers']};after={h['signature']:h for h in a['headers']};expected_sigs=set(before)|{x['signature']for x in N['functions']}
checks['170headers_exact_signatures']=set(after)==expected_sigs and len(after)==170
for x in D:before[x['signature']]={**before[x['signature']],'source_md5':x['candidate_prosrc_md5'],'config':x['config']}
checks['all_original_OID_ACL_config_attrs_preserved_except2configuration']=all({k:v for k,v in after[s].items()if k!='ddl_md5'}=={k:v for k,v in h.items()if k!='ddl_md5'}for s,h in before.items())
checks['4new_helpers_source_owner_grants_config_exact']=all({k:v for k,v in after[x['signature']].items()if k not in['oid','ddl_md5']}==x['expected_attributes']for x in N['functions'])
checks['existing_legal_dependencies_exact']=all(h==after[h['signature']]for h in a['legal_dependencies'])
checks['UI_and_recovery_unchanged']=all(new[k]==old[k]for k in ['ui','recovery'])
checks['actual_Edge98_exact_reviewed14files']=new['edge_bundles']==expected['edge_bundles'] and new['edge_bundles'][0]['version']==98
keys=['sha256','c1266_publication_envelope_proof']
checks['all_other_config_and_caps_preserved']={k:v for k,v in old['config'].items()if k!='sha256'}=={k:v for k,v in new['config'].items()if k not in keys}
checks['new_review_binding_exact']=new['config'][keys[1]]==expected['config'][keys[1]] and new['config']['sha256']==expected['config']['sha256']
checks['Root_db_and_code_identity_exact']=new['db_core']['sha256']==expected['db_core']['sha256'] and new['contract']==expected['contract']
checks['all_six_function_arrays_bind_actual_headers']=True
for key in ['pins','target_bodies','c1266_functions','all_function_headers','additional_dependencies','context24_functions']:
 for h in new['db_core'][key]:
  sig=h['signature'];sig=sig if sig in after else 'public.'+sig
  if sig in after:
   checks['all_six_function_arrays_bind_actual_headers'] &= all(str(v)==str(after[sig][k])for k,v in h.items()if k in after[sig] and k!='signature')
checks['all_other_Root_top_level_exact']={k:v for k,v in old.items()if k not in['config','db_core','contract','edge_bundles']}=={k:v for k,v in new.items()if k not in['config','db_core','contract','edge_bundles']}
checks['g2_only_release_changed']={k:v for k,v in b['g2'].items()if k!='release_sha256'}=={k:v for k,v in a['g2'].items()if k!='release_sha256'} and a['g2']['release_sha256']==a['root']['revision_sha256']
checks['authoring_admissions_only_release_changed']=[{k:v for k,v in x.items()if k!='release_sha256'}for x in b['admissions']]==[{k:v for k,v in x.items()if k!='release_sha256'}for x in a['admissions']] and all(x['release_sha256']==a['root']['revision_sha256']for x in a['admissions'])
checks['Root_authority_fields_preserved']={k:v for k,v in b['root'].items()if k not in['canonical_preimage','revision_sha256','observed_revision_sha256','client_build','updated_at']}=={k:v for k,v in a['root'].items()if k not in['canonical_preimage','revision_sha256','observed_revision_sha256','client_build','updated_at']}
root_sha=a['root']['revision_sha256'];checks['Root_live_hash_valid']=hashlib.sha256(a['root']['canonical_preimage'].encode()).hexdigest()==root_sha==a['root']['observed_revision_sha256']
for key in ['captured_at','root','headers','legal_dependencies','g2','admissions']:b.pop(key,None);a.pop(key,None)
checks['every_other_DB_snapshot_exact']=a==b
out={'schema_version':'c1266-legal-actions-postflight/1','status':'PASS'if all(checks.values())else'FAIL','PASS':all(checks.values()),'checks':checks,'recipe_sha256':sha('RECIPE.json'),'installer_sha256':sha('INSTALL.sql'),'root_sha256':root_sha,'provider_calls_by_checker':0,'runtime':'NOT_RUN'}
(P/'POSTFLIGHT_CHECK.json').write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out));sys.exit(0 if out['PASS']else 1)

