  select * into strict receipt from mission_narrative_internal.dispatch_receipts
    where id=w.dispatch_receipt_id for share;
  if b.state<>'ready' or b.message_id is not null
    or source_row.superseded_at is not null or source_row.consumed_message_id is not null
    or run_row.run_phase<>'in_corso' or run_row.current_step_key<>w.step_key
    or run_row.control_version<>w.run_control_version
    or w.payload->>'source_revision' is distinct from mission_generic_owner.role_source_revision_v1(p_session)
    or w.payload is distinct from b.payload or w.payload_sha256<>b.payload_sha256
    or w.result->>'work_id' is distinct from w.id::text
    or w.result->>'master_session_id' is distinct from p_session::text
    or w.result->>'request_key' is distinct from w.request_key::text
    or w.result->>'payload_sha256' is distinct from w.payload_sha256
    or receipt.status<>'success' or receipt.finalized_at is null
    or receipt.charged_cost_usd is null
    or exists(select 1 from mission_generic_owner.unified_segment_publications_v4
      where work_id=w.id)
  then raise exception 'MCR_SOURCE_CHANGED' using errcode='40001'; end if;

  if factory_cached and not exists(
   select 1 from mission_narrative_internal.dispatch_receipts nd
   join mission_narrative_internal.dispatch_audit ga on ga.receipt_id=nd.id and ga.event_code='generic_finalized'
   join mission_narrative_internal.dispatch_audit cp on cp.receipt_id=nd.id and cp.event_code='c8_count_success'
   join mission_narrative_internal.provider_authorizations pa on pa.id=w.authorization_id and pa.receipt_id=nd.id
   join mission_narrative_internal.dispatch_attempts na on na.receipt_id=nd.id and na.id=pa.attempt_id
   join staff_ai_quota_private.calls qc on qc.source_id=nd.id and qc.producer='mission_generic_ai' and qc.call_no=1
   where nd.id=w.dispatch_receipt_id and nd.authority_receipt_id=w.id and nd.master_session_id=p_session
    and nd.request_key=w.request_key and nd.status='success' and nd.dispatch_count=1 and nd.finalized_at is not null
    and nd.charged_cost_usd is not null and nd.lease_token_sha256 is null and nd.lease_expires_at is null
    and na.status='success' and na.finalized_at is not null and na.cost_basis='exact'
    and na.actual_cost_usd=nd.charged_cost_usd and qc.scope_id=p_session and qc.state='settled' and qc.charged_usd=nd.charged_cost_usd
    and ga.details->>'work_id'=w.id::text and ga.details->>'receipt_id'=w.receipt_id::text
    and ga.details->>'state'='failed' and ga.details->>'outcome_uncertain'='false'
    and ga.details->>'application_error_sqlstate'='42703'
    and ga.details->>'result_sha256'=w.result_sha256
    and ga.details->>'result_jsonb_sha256'=public.combat_v2_sha256(w.result)
    and cp.details->>'work_id'=w.id::text and cp.details->>'state'='success'
    and cp.details->>'generation_allowed'='true' and cp.details->>'input_tokens'='10066'
    and cp.details->>'max_input_tokens'='12000'
    and w.authority_receipt_id='08512119-3bfd-4df7-adbc-0686f5edf5b7'::uuid
    and w.definition_sha256='49817335c60ce9d4b47bc5d81c6950f622635c7fb232264ab54736349124f567'
    and w.result->>'schema_version'='mission-generic-result/2' and jsonb_typeof(w.result->'segments')='array'
    and w.result->'text'='null'::jsonb
    and not exists(select 1 from mission_generic_owner.work_items other where other.master_session_id=p_session and other.state in('claimed','authorized','provider_started','uncertain'))
    and not exists(select 1 from mission_narrative_internal.dispatch_attempts pending join mission_narrative_internal.dispatch_receipts pd on pd.id=pending.receipt_id where pd.master_session_id=p_session and pending.finalized_at is null)
  ) then raise exception 'MCR_FACTORY_CACHED_RECEIPT' using errcode='40001';end if;
  perform mission_generic_owner.work_assert(w);

  begin
    update mission_generic_owner.work_items set state='provider_started',finalized_at=null
      where id=w.id and state='failed';
    result_row:=mission_generic_owner.unified_publish_v4(
      w.id,w.result,w.request_key,w.result_sha256);
    message_ref:=(result_row->>'message_id')::uuid;
    if message_ref is null then raise exception 'MCR_PUBLICATION_MISSING'; end if;
    update mission_generic_owner.work_items
      set state='completed',finalized_at=clock_timestamp(),message_id=message_ref,
        result=result||jsonb_build_object('text',result_row->>'text','continuity',result_row->'continuity'),
        result_sha256=public.combat_v2_sha256(result||jsonb_build_object(
          'text',result_row->>'text','continuity',result_row->'continuity'))
      where id=w.id and state='provider_started';
    if not found then raise exception 'MCR_WORK_CAS'; end if;
  exception when others then
    get stacked diagnostics error_state=returned_sqlstate,error_message=message_text,
      error_constraint=constraint_name,error_table=table_name,error_schema=schema_name,
      diagnostic_column=column_name,diagnostic_context=pg_exception_context,native_selection_detail=pg_exception_detail;
    IF error_state='55000' AND error_message='MRS_V4_NO_LEGAL_NATIVE_ATTACK' AND octet_length(native_selection_detail)<=8192 THEN
      BEGIN
        native_selection_diagnostic:=native_selection_detail::jsonb;
        IF mission_factory_owner.keys_exact_v2(native_selection_diagnostic,ARRAY['schema_version','actor_key','round_phase','counts','producer_counts','producer_called']) IS DISTINCT FROM true
          OR native_selection_diagnostic->>'schema_version' IS DISTINCT FROM 'mission-native-attack-selection-diagnostic/2'
          OR coalesce(native_selection_diagnostic->>'actor_key','')!~'^[a-z][a-z0-9_]{0,63}$'
          OR coalesce(native_selection_diagnostic->>'round_phase','') NOT IN('raccolta_azioni','raccolta_difese','risoluzione','risolto','narrazione','narrato','other')
          OR mission_factory_owner.keys_exact_v2(native_selection_diagnostic->'counts',ARRAY['actor_offers','principal_match','offered','action','master_adapter','action_dispatch','attack','mano','in_projection','no_required_inputs','supported_groups','candidate_count','shape_rejected','pg_target_count','multiple_move_groups','move_shape_rejected','move_option_missing','extra_dependency_rejected']) IS DISTINCT FROM true
          OR jsonb_typeof(native_selection_diagnostic->'producer_called') IS DISTINCT FROM 'boolean'
          OR mission_factory_owner.keys_exact_v2(native_selection_diagnostic->'producer_counts',ARRAY['targets_total','targets_seen','mano_seen','geometry_stay','endpoint_count','pending_count','rejected_geometry','label_present','legal_total','action_entered']) IS DISTINCT FROM true
          OR EXISTS(SELECT 1 FROM jsonb_each(native_selection_diagnostic->'producer_counts') x WHERE jsonb_typeof(x.value) IS DISTINCT FROM 'number' OR (x.value#>>'{}')!~'^[0-9]{1,6}$')
          OR EXISTS(SELECT 1 FROM jsonb_each(native_selection_diagnostic->'counts') x WHERE jsonb_typeof(x.value) IS DISTINCT FROM 'number' OR (x.value#>>'{}')!~'^[0-9]{1,6}$')
        THEN native_selection_diagnostic:=NULL;END IF;
      EXCEPTION WHEN invalid_text_representation OR invalid_parameter_value THEN native_selection_diagnostic:=NULL;END;
    END IF;
    if factory_cached then
      if diagnostic_column !~ '^[A-Za-z_][A-Za-z0-9_]{0,62}$' then diagnostic_column:=null;end if;
      if diagnostic_column is null and error_state='42703' then
        diagnostic_column:=coalesce(
          substring(error_message from '^column "([A-Za-z_][A-Za-z0-9_]{0,62})" does not exist$'),
          substring(error_message from '^record "[A-Za-z_][A-Za-z0-9_]{0,62}" has no field "([A-Za-z_][A-Za-z0-9_]{0,62})"$'),
          substring(error_message from '^column [A-Za-z_][A-Za-z0-9_]{0,62}\.([A-Za-z_][A-Za-z0-9_]{0,62}) does not exist$'));
      end if;
      if error_table !~ '^[A-Za-z_][A-Za-z0-9_]{0,62}$' then error_table:=null;end if;
      if error_schema !~ '^[A-Za-z_][A-Za-z0-9_]{0,62}$' then error_schema:=null;end if;
      select coalesce(jsonb_agg(jsonb_build_object('function',parts[1],'line',parts[2]::integer) order by ordinal),'[]'::jsonb) into diagnostic_frames
        from (select parts,ordinal from regexp_matches(diagnostic_context,'PL/pgSQL function ([A-Za-z_][A-Za-z0-9_.]*)\([^)]*\) line ([0-9]{1,6})','g') with ordinality f(parts,ordinal) limit 8) frames;
    end if;
    safe_code:=case when error_message ~ '^[A-Z][A-Z0-9_]{1,79}$'
      then error_message else 'SQLSTATE_'||error_state end;
  end;
  if safe_code is not null then
    insert into mission_narrative_internal.dispatch_audit(receipt_id,event_code,details)
      values(receipt.id,'staff_cached_publication_rejected',jsonb_build_object(
        'work_id',w.id,'master_session_id',p_session,
        'sqlstate',error_state,'error_code',safe_code,
        'constraint_name',nullif(error_constraint,''),
        'table_name',nullif(error_table,''),
        'schema_name',nullif(error_schema,'')) || CASE WHEN native_selection_diagnostic IS NOT NULL THEN jsonb_build_object('private_native_attack_selection',native_selection_diagnostic) ELSE '{}'::jsonb END || case when factory_cached then jsonb_build_object('private_diagnostics',jsonb_build_object('schema_version','c1264-cached-private-error/1','column',diagnostic_column,'table',error_table,'schema',error_schema,'frames',diagnostic_frames)) else '{}'::jsonb end);
    return jsonb_build_object('schema_version','mission-generic-staff-cached-publication/1',
      'status','failed','error_code',safe_code);
  end if;
  insert into mission_narrative_internal.dispatch_audit(receipt_id,event_code,details)
    values(receipt.id,'staff_cached_publication_completed',jsonb_build_object(
      'work_id',w.id,'master_session_id',p_session,'message_id',message_ref));
  return jsonb_build_object('schema_version','mission-generic-staff-cached-publication/1',
    'status','published','message_id',message_ref,'replayed',false);
end
$function$

mission_generic_owner.combat_narration_r.source:
CREATE OR REPLACE FUNCTION mission_generic_owner.combat_narration_reissue_proof_v1(p_work uuid,p_user uuid) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path TO '' AS $function$
DECLARE w mission_generic_owner.work_items;b mission_generic_owner.unified_batches;m public.master_v2_sessions;rs public.mission_run_state;dr mission_narrative_internal.dispatch_receipts;su mission_generic_owner.work_items;au mission_narrative_internal.dispatch_audit;who uuid;sid uuid;ev uuid;rq uuid;req jsonb;rep public.combat_v2_round_reports;cfg jsonb;published boolean:=false;
BEGIN
 IF p_work IS NULL OR p_user IS NULL OR(auth.uid() IS NOT NULL AND auth.uid()<>p_user) THEN RETURN NULL;END IF;
 SELECT * INTO w FROM mission_generic_owner.work_items WHERE id=p_work;
 IF NOT FOUND OR w.kind<>'narration' OR w.state<>'failed' OR w.message_id IS NOT NULL OR w.finalized_at IS NULL
  OR w.authorization_id IS NOT NULL OR w.dispatch_id IS NOT NULL OR w.payload->>'schema_version'<>'mission-generic-narration/3'
  OR w.payload->>'composition_kind' NOT IN('combat_defense_resolved','combat_resolved_no_pending','combat_resolved_then_png_offensive','combat_exit')
  OR w.payload_sha256 IS DISTINCT FROM public.combat_v2_sha256(w.payload) OR w.result_sha256 IS DISTINCT FROM public.combat_v2_sha256(w.result)
  OR w.result->>'schema_version' IS DISTINCT FROM 'mission-generic-pre-provider-failure/1' OR w.result->>'failure_code' IS DISTINCT FROM 'request_validation_failed'
  OR w.result->>'work_id' IS DISTINCT FROM w.id::text OR w.result->>'provider_calls' IS DISTINCT FROM '0' OR w.result->>'charged_cost_usd' IS DISTINCT FROM '0' THEN RETURN NULL;END IF;
 SELECT * INTO m FROM public.master_v2_sessions WHERE id=w.master_session_id;
 IF m.owner_kind<>'ai_service' OR m.master_user IS NOT NULL OR m.location_id<>'0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid OR m.closed_at IS NOT NULL OR m.suspended_at IS NOT NULL
  OR NOT EXISTS(SELECT 1 FROM public.locations l WHERE l.id=m.location_id AND l.is_test AND l.is_active)
  OR NOT EXISTS(SELECT 1 FROM public.profiles pr JOIN public.master_v2_participants mp ON mp.user_id_snapshot=pr.id JOIN public.characters ch ON ch.id=mp.character_id AND ch.user_id=mp.user_id_snapshot WHERE pr.id=p_user AND pr.role IN('admin','master') AND mp.session_id=m.id AND mp.left_at IS NULL AND mp.engagement_state='attivo')
  OR mission_generic_owner.manual_staff_scope_v1(m.id) IS NULL THEN RETURN NULL;END IF;
 SELECT r.canonical_preimage::jsonb#>'{config,c1266_combat_snapshot_recovery}' INTO cfg FROM mission_factory_owner.editor_release_readiness r WHERE r.singleton AND r.state='enabled' AND r.revision_sha256=r.observed_revision_sha256;
 IF cfg->>'enabled' IS DISTINCT FROM 'true' OR cfg->>'master_session_id' IS DISTINCT FROM m.id::text OR cfg->>'ordinary_public_enabled' IS DISTINCT FROM 'false' THEN RETURN NULL;END IF;
 SELECT * INTO b FROM mission_generic_owner.unified_batches WHERE id=w.authority_receipt_id AND master_session_id=m.id;
 IF NOT FOUND OR b.retired_at IS NOT NULL OR b.payload IS DISTINCT FROM w.payload OR b.payload_sha256 IS DISTINCT FROM w.payload_sha256 OR b.source_window_id IS NOT NULL
  OR b.source_round_id IS NULL OR b.source_report_id IS NULL OR b.encounter_id IS DISTINCT FROM w.encounter_id OR b.step_key IS DISTINCT FROM w.step_key OR b.run_control_version IS DISTINCT FROM w.run_control_version
  OR b.composition_kind IS DISTINCT FROM w.payload->>'composition_kind' THEN RETURN NULL;END IF;
 SELECT * INTO rep FROM public.combat_v2_round_reports WHERE id=b.source_report_id AND round_id=b.source_round_id;
 IF NOT FOUND OR rep.values_written IS DISTINCT FROM false OR rep.mechanics_sha256 IS DISTINCT FROM public.combat_v2_sha256(rep.mechanics)
  OR NOT EXISTS(SELECT 1 FROM public.combat_v2_rounds r JOIN public.combat_v2_sessions cs ON cs.id=r.session_id WHERE r.id=b.source_round_id AND r.session_id=b.encounter_id AND cs.master_session_id=m.id AND NOT public.combat_v2_values_written(cs.id))
  OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(w.payload->'resolved_scenes') x WHERE x#>>'{scene_binding,round_id}'=b.source_round_id::text AND x#>>'{scene_binding,session_id}'=b.encounter_id::text AND x#>>'{scene_binding,report_sha256}'=rep.mechanics_sha256 AND x#>'{barrier,required_receipt_ids}' @> jsonb_build_array(rep.id))
  OR w.payload#>>'{publication_barrier,closed}' IS DISTINCT FROM 'true' OR w.payload#>'{publication_barrier,receipt_ids}' IS DISTINCT FROM w.payload#>'{publication_barrier,required_receipt_ids}'
  OR NOT(w.payload#>'{publication_barrier,receipt_ids}' @> jsonb_build_array(b.id,b.source_report_id)) THEN RETURN NULL;END IF;
 SELECT * INTO dr FROM mission_narrative_internal.dispatch_receipts WHERE id=w.dispatch_receipt_id;
 IF NOT FOUND OR dr.master_session_id<>m.id OR dr.authority_receipt_id<>w.id OR dr.request_key<>w.request_key OR dr.status<>'failed' OR dr.dispatch_count<>0 OR dr.finalized_at IS NULL OR dr.charged_cost_usd IS DISTINCT FROM 0 OR dr.upper_bound_cost_usd IS DISTINCT FROM 0
  OR EXISTS(SELECT 1 FROM mission_narrative_internal.provider_authorizations pa WHERE pa.receipt_id=dr.id)
  OR EXISTS(SELECT 1 FROM staff_ai_quota_private.calls q WHERE q.producer='mission_generic_ai' AND q.source_id=dr.id)
  OR NOT EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_audit a WHERE a.receipt_id=dr.id AND a.event_code='generic_pre_provider_failed' AND a.details->>'work_id'=w.id::text AND a.details->>'receipt_id'=w.receipt_id::text AND a.details->>'result_sha256'=w.result_sha256 AND a.details->>'failure_code'='request_validation_failed' AND a.details->>'provider_calls'='0' AND a.details->>'charged_cost_usd'='0') THEN RETURN NULL;END IF;
 SELECT (a.details->>'actor_user_id')::uuid INTO who FROM mission_narrative_internal.dispatch_audit a WHERE a.receipt_id=dr.id AND a.event_code='c1266_async_owner_v1' AND a.details->>'work_id'=w.id::text;
 IF who IS NULL THEN RETURN NULL;END IF;
 sid:=mission_ai_service_owner.uuid5(w.id,'mission-combat-narration-reissue/1:work');ev:=mission_ai_service_owner.uuid5(w.id,'mission-combat-narration-reissue/1:event');rq:=mission_ai_service_owner.uuid5(w.id,'mission-combat-narration-reissue/1:request');
 SELECT * INTO su FROM mission_generic_owner.work_items WHERE id=sid;
 SELECT * INTO au FROM mission_narrative_internal.dispatch_audit a WHERE a.receipt_id=dr.id AND a.event_code='staff_combat_narration_preprovider_reissued';
 IF su.id IS NOT NULL THEN
  IF b.writer_work_id IS DISTINCT FROM su.id OR su.kind<>'narration' OR su.master_session_id<>m.id OR su.authority_receipt_id<>b.id OR su.event_id<>ev OR su.request_key<>rq OR su.payload IS DISTINCT FROM w.payload OR su.payload_sha256<>w.payload_sha256 OR su.step_key<>w.step_key OR su.run_control_version<>w.run_control_version OR su.definition_sha256<>w.definition_sha256
   OR au.id IS NULL OR au.details->>'failed_work_id' IS DISTINCT FROM w.id::text OR au.details->>'successor_work_id' IS DISTINCT FROM su.id::text OR au.details->>'payload_sha256' IS DISTINCT FROM w.payload_sha256 OR au.details->>'report_sha256' IS DISTINCT FROM rep.mechanics_sha256 OR au.details->>'actor_user_id' IS DISTINCT FROM who::text OR au.details->>'provider_calls' IS DISTINCT FROM '0' THEN RETURN NULL;END IF;
  req:=jsonb_build_object('schema_version','mission-generic-request/1','master_session_id',m.id,'event_id',su.event_id,'request_key',su.request_key,'expected_revision',su.revision);
  published:=b.state='published' AND su.state='completed' AND b.message_id IS NOT NULL AND su.message_id=b.message_id AND rep.message_id=b.message_id AND EXISTS(SELECT 1 FROM public.messages mm WHERE mm.id=b.message_id AND mm.kind='fato' AND mm.location_id=m.location_id AND mm.character_id IS NULL AND mm.recipient_user IS NULL);
 ELSE
  IF b.writer_work_id IS DISTINCT FROM w.id OR au.id IS NOT NULL THEN RETURN NULL;END IF;
 END IF;
 IF NOT published THEN
  SELECT * INTO rs FROM public.mission_run_state WHERE master_session_id=m.id;
  IF b.state<>'ready' OR b.message_id IS NOT NULL OR rep.narration_state<>'attesa' OR rep.message_id IS NOT NULL OR rs.run_phase<>'in_corso' OR rs.current_step_key<>w.step_key OR rs.control_version<>w.run_control_version OR NOT EXISTS(SELECT 1 FROM public.combat_v2_rounds WHERE id=b.source_round_id AND state='risolto') THEN RETURN NULL;END IF;
 END IF;
 RETURN jsonb_build_object('schema_version','mission-combat-narration-reissue-proof/1','master_session_id',m.id,'failed_work_id',w.id,'batch_id',b.id,'report_id',rep.id,'report_sha256',rep.mechanics_sha256,'payload_sha256',w.payload_sha256,'owned_by_me',who=p_user,'can_reissue',who=p_user AND su.id IS NULL,'successor_work_id',su.id,'successor_request',req,'can_resume',who=p_user AND su.id IS NOT NULL AND su.state='ready' AND su.finalized_at IS NULL,'actor_user_id',who,'audit_sha256',CASE WHEN au.id IS NULL THEN NULL ELSE public.combat_v2_sha256(au.details) END,'published',published);
END
$function$;
ALTER FUNCTION mission_generic_owner.combat_narration_reissue_proof_v1(uuid,uuid) OWNER TO postgres;
REVOKE ALL ON FUNCTION mission_generic_owner.combat_narration_reissue_proof_v1(uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION mission_generic_owner.combat_narration_reissue_proof_v1(uuid,uuid) TO service_role;

mission-generic-runtime.mjs.source:
import {scenePrompts, inspectNarrative} from './exam_regia17/edge/src/shared-scene/editorial.mjs';
import {editorialPrompt, EDITORIAL_VERSION, PLAYER_CONTEXT_RULE} from './exam_regia17/edge/src/shared-scene/common.mjs';
import {editorialPrompt as staffEditorialPrompt, EDITORIAL_VERSION as STAFF_EDITORIAL_VERSION, PLAYER_CONTEXT_RULE as STAFF_PLAYER_CONTEXT_RULE} from './exam_regia17/edge/src/shared-scene/staff-common.mjs';
import {digest, canonical} from './exam_regia17/edge/src/shared-scene/scene.mjs';
import {PROVIDER} from './exam_regia17/edge/src/contracts.mjs';
import {choiceContext, choiceRequest as commonChoiceRequest, choiceCommand, choiceProfileAudit,
  profileAuditSchema, validateProfileAudit, NARRATIVE_AUDIT_SECTIONS, CHOICE_VERSION} from './mission-generic-choice.mjs';

export const RUNTIME_VERSION = 'mission-generic-runtime/1'; // Native dispatcher/accounting contract remains unchanged.
export const SEGMENTED_RUNTIME_VERSION = 'mission-generic-runtime/2'; // Candidate only: DB finalizer/publisher /4 required.
export const MISSION_DIRECTOR_VERSION = 'mission-director-editorial/6';
const STAFF_MISSION_DIRECTOR_VERSION = 'mission-director-editorial/7';
export const MISSION_EDITORIAL_VERSION = 'mission-editorial-lifecore/12';
export const CONTINUITY_VERSION = 'mission-continuity/1';
const LEGACY_MISSION_EDITORIAL_VERSION = 'mission-editorial-lifecore/8';
const LEGACY_ROLE_WINDOW_RULE = "Le role dei PG incluse nella finestra certificata dal server possono precedere un Fato di contesto della stessa fase: considerale insieme con le nuove role, in ordine cronologico. Distingui ciò che il Fato precedente ha già narrato da ciò che resta da raccordare; non ripetere né riassumere ciò che hanno scritto i giocatori.";
const isCinematic = work => work?.narrative_profile === 'cinematic_master_1';
// Cinematic is an editorial profile, never a Staff permission or resource policy.
const hasAdmission = work => work?.narrative_admission != null;
const retainsProviderOutput=work=>work?.narrative_admission?.scope==='staff_mission'&&work.narrative_admission.features?.includes('provider_output_retention_v1')===true;
const freeNarrative=work=>retainsProviderOutput(work)&&work.kind==='narration'&&work.payload?.schema_version==='mission-generic-narration/4'&&work.narrative_admission.features.includes('free_narrative_v1');
const nativeIntentResolution=work=>work?.narrative_admission?.schema_version==='mission-narrative-admission/3'&&work.narrative_admission.scope==='staff_mission'&&work.narrative_admission.features?.includes('native_intent_resolution_v1')===true;
const combatSnapshotOriginBudget=work=>work?.narrative_admission?.schema_version==='mission-narrative-admission/3'&&work.narrative_admission.scope==='staff_mission'&&work.kind==='narration'&&work.narrative_admission.payload_schema_version==='mission-generic-narration/3'&&work.narrative_admission.features?.includes('combat_snapshot_origin_budget_v1')===true;
const hasFeature = (work,feature) => hasAdmission(work)
  ? work.narrative_admission.features.includes(feature) : isCinematic(work);
// Attested admission /3 is exclusively public Quest; /1 and /2 keep their closed scopes.
const isAttestedAdmission = work => ['mission-narrative-admission/2','mission-narrative-admission/3'].includes(work?.narrative_admission?.schema_version);
// References are private to this validated claim; nested formatters retain the same
// admission object without manufacturing new payload or SQL hashes.
const attestedSources = new WeakMap();
const providerInputContracts = new WeakMap();

// Exact Schema7bc473 Source, isolated namespace; preserves the live fourteen-file bundle.
const RoleIntentSchema=(()=>{
// SOURCE ONLY. Not imported by runtime; no mechanics, publishing, policy decisions or provider calls.
// Authority must be constructed from the immutable current server work, never model/client data.
const ROLE_INTENT_CONTRACT_SHA256='e7762d6d253f00236fe7dcda2135155203aacf70374741c34441cac1dcb8de01';
const ROLE_INTENT_FREEZE_SHA256='97c5d14fb6f13502c7b560a126801fedb8855e04f91ac2a874c3a4107af51fb8';
const object=x=>x!==null&&typeof x==='object'&&!Array.isArray(x);
