  // Counting ALL public refs below remains a conservative upper bound, including unused role catalogs.
  // Reserve the role_id singleton added for each source_evidence alternative too.
  const planEntries=c1266PlanSegments(work);
  const basisPublicCount=validated.descriptor.public_source_refs.filter(s=>s.source_kind==='fato').length;
  const quoteWeight=5*validRoleCount+(roster.participants.length+1)*validated.descriptor.public_source_refs.length+basisPublicCount;
  const selectionReserve=planEntries.length+16+2*work.payload.opportunities.length;
