      const noncanonical=JSON.parse(JSON.stringify(destination));
      noncanonical.properties.kind={type:'string',enum:row.role_status==='valid'?['none','undetermined']:['undetermined']};
      noncanonical.properties.step_key={type:'null'};
      noncanonical.properties.public_proof.minItems=0;noncanonical.properties.public_proof.maxItems=0;
      const orientationRefs=refs.filter(ref=>['fato','setting','entry_public'].includes(ref.source_kind));
      const steps=roleFor(work).descriptor.destination_step_keys;
      const variants=[];
      if(row.role_status==='valid'&&orientationRefs.length&&steps.length){
        const canonical=JSON.parse(JSON.stringify(destination));
        canonical.properties.kind={type:'string',enum:['canonical']};
        canonical.properties.step_key={type:'string',enum:[...steps]};
        canonical.properties.public_proof.minItems=1;
