checks['all_gameplay_history_rows_exact']=e==f
checks['zero_active_and10Fati20roles48fields']=f['active_work_count']==0 and len(f['fati'])==11 and len(f['roles'])==20 and a['protected']==b['protected'] and a['protected']['protected_field_count']==48
