before={h['signature']:h for h in b['headers']+b['legal_dependencies']};after={h['signature']:h for h in a['headers']};expected_sigs=set(before)|{x['signature']for x in N['functions']}
checks['171headers_exact_signatures']=set(after)==expected_sigs and len(after)==171
for x in D:before[x['signature']]={**before[x['signature']],'source_md5':x['candidate_prosrc_md5']}
checks['all_original_OID_ACL_config_attrs_preserved_except4bodies']=all({k:v for k,v in after[s].items()if k!='ddl_md5'}=={k:v for k,v in h.items()if k!='ddl_md5'}for s,h in before.items())
checks['1new_helper_source_owner_grants_config_exact']=all({k:v for k,v in after[x['signature']].items()if k not in['oid','ddl_md5']}==x['expected_attributes']for x in N['functions'])
checks['existing_legal_dependencies_exact']=all(h==after[h['signature']]for h in a['legal_dependencies'])
checks['UI_actual2_and_recovery_exact']=new['ui']==expected['ui'] and new['recovery']==old['recovery']
checks['actual_Edge99_exact_reviewed14files']=new['edge_bundles']==expected['edge_bundles'] and new['edge_bundles'][0]['version']==99
keys=['sha256',r('ROOT_CONFIG_DELTA.json')['config_key'],'c1266_combat_writer_recovery_proof']
checks['all_other_config_and_caps_preserved']={k:v for k,v in old['config'].items()if k!='sha256'}=={k:v for k,v in new['config'].items()if k not in keys}
