  const numericWire=typeof wire==='string'&&/^(?:mission-director-numeric-catalog\/1|mission-director-peer-confirmation\/[12]):[a-fA-F0-9]{8}(?:-[a-fA-F0-9]{4}){3}-[a-fA-F0-9]{12}$/.test(wire);
