function providerDiagnostic43(value) {
  try {
    if(!object(value))return null;
    const keys=['schema_version','http_status','response_id','request_id','status','incomplete_reason','parse_state','usage_state','error_code','error_type','error_param'];
    if(!exact(value,keys)||value.schema_version!=='mission-provider-diagnostic/1')return null;
    if(value.http_status!==null&&(!Number.isInteger(value.http_status)||value.http_status<100||value.http_status>599))return null;
    if(['response_id','request_id'].some(k=>value[k]!==null&&(typeof value[k]!=='string'||!/^[A-Za-z0-9_-]{1,200}$/.test(value[k]))))return null;
    const enums={status:['completed','failed','in_progress','cancelled','queued','incomplete','UNKNOWN','ABSENT'],incomplete_reason:['max_output_tokens','max_messages','content_filter','steered','UNKNOWN','ABSENT'],parse_state:['NOT_ATTEMPTED','VALID','MISSING','MALFORMED','REFUSAL','MULTIPLE','UNKNOWN_TYPE'],usage_state:['VALID','MISSING','INVALID','IGNORED_NONTERMINAL'],error_code:[null,'invalid_json_schema','context_length_exceeded','unsupported_value','model_not_found','rate_limit_exceeded','insufficient_quota'],error_type:[null,'invalid_request_error','rate_limit_error','server_error'],error_param:[null,'model','input','reasoning.effort','text.format.schema']};
    if(Object.entries(enums).some(([k,v])=>!v.includes(value[k])))return null;
    const out=Object.fromEntries(keys.map(k=>[k,value[k]]));return bytes(out)<=1024?out:null;
  } catch {return null;}
}

function usageOf(out) {
  const m = out?.metrics;
  if (!object(m) || ['input_tokens','output_tokens','reasoning_tokens','total_tokens'].some(k=>!Number.isSafeInteger(m[k]) || m[k] < 0)) return null;
  return Object.fromEntries(['input_tokens','output_tokens','reasoning_tokens','total_tokens'].map(k=>[k,m[k]]));
}

