(P/'INSTALL.sql').write_text(s);save('BOUND_MANIFEST.json',{'recipe':ref('RECIPE.json'),'builder':ref('BUILD_INTEGRATED.py'),'review':ref('INTEGRATED_REVIEW.json'),'installer':ref('INSTALL.sql'),'existing_bodies_changed':6,'new_helpers':1,'UI_files_changed':0,'provider_calls':0});print(canon({'installer':ref('INSTALL.sql'),'status':'BOUND_AWAITING_MATERIAL_REVIEW'}))

