P=Path(__file__).parent;r=lambda n:json.loads((P/n).read_text());sha=lambda n:hashlib.sha256((P/n).read_bytes()).hexdigest()
b=r('DB_BEFORE.json');a=r('DB_AFTER.json');e=r('EXTRA_BEFORE.json');f=r('EXTRA_AFTER.json');D=r('SQL_DELTA.json');N=r('NEW_OBJECTS.json');old=json.loads(b['root']['canonical_preimage']);new=json.loads(a['root']['canonical_preimage']);expected=r('EXPECTED_ROOT.json');c={}
