c['all_original_attrs_OID_exact_except6bodyMD5']=all({k:v for k,v in h.items()if k!='ddl_md5'}=={k:v for k,v in after[s].items()if k!='ddl_md5'} for s,h in before.items())
c['new_owner_only_helper_exact']=all({k:v for k,v in after[n['signature']].items()if k not in['oid','ddl_md5']}==n['expected_attributes'] for n in N['functions'])
c['UI_recovery_unchanged']=new['ui']==old['ui'] and new['recovery']==old['recovery']
c['Edge100exactactual']=new['edge_bundles']==expected['edge_bundles'] and new['edge_bundles'][0]['version']==100
key='c1266_read_performance_business_error_proof';c['other_config_caps_unchanged']={k:v for k,v in new['config'].items()if k not in['sha256',key]}=={k:v for k,v in old['config'].items()if k!='sha256'}
c['new_config_review_exact']=new['config']==expected['config']
c['db_identity_and_contract_exact']=new['db_core']['sha256']==expected['db_core']['sha256'] and new['contract']==expected['contract']
c['all6header_arrays_actual']=True
for k in ['pins','target_bodies','c1266_functions','all_function_headers','additional_dependencies','context24_functions']:
 for h in new['db_core'][k]:
  sig=h['signature'];sig=sig if sig in after else 'public.'+sig
  if sig in after:c['all6header_arrays_actual'] &= all(str(v)==str(after[sig][key]) for key,v in h.items()if key in after[sig] and key!='signature')
c['other_Root_top_exact']={k:v for k,v in new.items()if k not in['config','db_core','contract','edge_bundles']}=={k:v for k,v in old.items()if k not in['config','db_core','contract','edge_bundles']}
c['Root_hash_valid']=hashlib.sha256(a['root']['canonical_preimage'].encode()).hexdigest()==a['root']['revision_sha256']==a['root']['observed_revision_sha256']
B=copy.deepcopy(b);A=copy.deepcopy(a)
for obj in [B,A]:
 for k in ['captured_at','headers']:obj.pop(k,None)
 for k in ['canonical_preimage','revision_sha256','observed_revision_sha256','client_build','updated_at']:obj['root'].pop(k,None)
 obj['g2'].pop('release_sha256',None)
 for ad in obj['admissions']:ad.pop('release_sha256',None)
c['every_other_DB_field_exact']=A==B
c['g2_admissions_only_newRoot']=a['g2']['release_sha256']==a['root']['revision_sha256'] and all(ad['release_sha256']==a['root']['revision_sha256']for ad in a['admissions'])
out={'schema_version':'mission-read-performance-postflight/1','status':'PASS'if all(c.values())else'FAIL','PASS':all(c.values()),'checks':c,'recipe_sha256':sha('RECIPE.json'),'installer_sha256':sha('INSTALL.sql'),'root_sha256':a['root']['revision_sha256'],'provider_calls_by_checker':0,'runtime':'NOT_RUN'};(P/'POSTFLIGHT_CHECK.json').write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out));sys.exit(0 if out['PASS']else 1)

