from pathlib import Path
import json,hashlib,shutil,argparse,re,math
P=Path(__file__).resolve().parent;R=P.parent;I=R/'read_performance_correction';NAMES=['C1266_LEGAL_ACTIONS_SOURCE.json','C1266_LEGAL_ACTIONS_PROOF.json'];ROOT='C1266_LEGAL_ACTIONS_ROOT.sql'
def read(p):return json.loads(p.read_text())
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def ref(p):return {'path':str(p),'bytes':p.stat().st_size,'sha256':sha(p)}
def source(p):return {**ref(p),'source':p.read_text()}
def safe_runtime(path):
 path=path.resolve();assert path.is_relative_to(R) and path.is_file(),'Runtime metadata outside task'
 raw=read(path);out={}
 strings={'schema_version':r'^[a-z0-9][a-z0-9_/-]{0,99}$','status':r'^[A-Z][A-Z0-9_]{0,99}$','root_sha256':r'^[a-f0-9]{64}$','message_id':r'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','published_at':r'^[0-9TtZz:+. -]{10,40}$','resume_claim_sqlstate':r'^[A-Z0-9]{5}$','reachability_checked_at':r'^[0-9TtZz:+. -]{10,40}$','connection_error_code':r'^CONNECTION_TIMEOUT$'}
 booleans=['publication_attested','published','mission_complete_attested','protected_fields_preserved','previous_Fati_preserved','current_successor_state_verified','native_PG_defense_accepted','fresh_baseline_available','reachability_probe_succeeded','read_performance_applied','read_performance_installable']
 counts=['provider_calls','count_calls','generation_calls','http_calls','generic_role_submission_count','protected_fields_count','old_fati_count']
 amounts=['total_conservative_run_usd','budget_usd','headroom_usd']
 for k,pattern in strings.items():
  if k in raw:
   assert isinstance(raw[k],str) and re.fullmatch(pattern,raw[k]),'Invalid runtime metadata: '+k;out[k]=raw[k]
 for k in booleans:
  if k in raw:assert raw[k] is None or type(raw[k]) is bool,'Invalid runtime flag';out[k]=raw[k]
 for k in counts:
  if k in raw:assert raw[k] is None or type(raw[k]) is int and raw[k]>=0,'Invalid runtime count';out[k]=raw[k]
 for k in amounts:
  if k in raw:assert raw[k] is None or type(raw[k]) in [int,float] and math.isfinite(raw[k]) and raw[k]>=0,'Invalid runtime cost';out[k]=raw[k]
 if 'editorial_quality' in raw:assert raw['editorial_quality'] in ['NOT_ATTESTED','FAILED_OBSERVED','REVIEWED_PASS'];out['editorial_quality']=raw['editorial_quality']
 if 'last_verified_successor_state' in raw:assert raw['last_verified_successor_state'] in ['ready','claimed','authorized','provider_started','completed','failed','uncertain'];out['last_verified_successor_state']=raw['last_verified_successor_state']
 return out
def build(input_dir=None,runtime_path=None):
 C=Path(input_dir) if input_dir else P/'round_writer_final';O=P/'performance_pending';seeds={n:read(C/n) for n in NAMES};before_refs={n:ref(C/n)for n in NAMES};packet=read(I/'SOURCE_REVIEW_PACKET.json');assert packet['state']=='SOURCE_ONLY_NOT_INSTALLABLE' and packet['fresh_baseline']=='BLOCKED_CONNECTION_TIMEOUT'
 review=read(I/'SOURCE_REVIEW.json');assert review['source_packet_sha256']==sha(I/'SOURCE_REVIEW_PACKET.json') and review['findings_count']=={'P0':0,'P1':0,'P2':0} and review['status']=='PASS_SOURCE_ONLY_NOT_INSTALLABLE'
 safe={};snapshots={}
 for m in packet['refs']:
  p=Path(m['path']);assert p.is_relative_to(I) and p.stat().st_size==m['bytes'] and sha(p)==m['sha256'],'Source packet drift'
  if p.name in ['DB_LAST_VERIFIED.json','EXTRA_LAST_VERIFIED.json']:snapshots[p.name]={**ref(p),'source_omitted':'Last verified snapshot reference only, NOT a fresh baseline; no DB snapshot bodies are exported.'};continue
  safe[str(p.relative_to(I))]=source(p)
 sql={k:v for k,v in safe.items() if k.startswith('db_author/candidate/') and k.endswith('.sql')};assert len(sql)==4
 pending={'schema_version':'c1266-read-performance-pending-delivery/1','release_key':sha(I/'SOURCE_REVIEW_PACKET.json'),'status':'NOT_INSTALLABLE_NOT_APPLIED','live_baseline':'LIVE_BASELINE_BLOCKED','last_installed_root':'871bf3116ee460a121e57372f41eb4f520b5fa66125afd413556641d137ab02e','current_edge_version':99,'current_UI_commit':'233f432ad63ed9a12fca557fbff7d6ea340f5adf','candidate_scope':'3existing function bodies+1owner-onlyhelper;4SQLsources only. No installer, no live preflight, no apply and no server performance PASS.','source_packet':source(I/'SOURCE_REVIEW_PACKET.json'),'source_review':source(I/'SOURCE_REVIEW.json'),'source_files':safe,'last_snapshot_refs':snapshots,'provider_calls':0,'runtime':'NOT_RUN_SOURCE_ONLY'}
 current=safe_runtime(runtime_path) if runtime_path else {'schema_version':'c1266-legal-actions-runtime-proof/1','status':'CONNECTION_BLOCKED_MISSION_INCOMPLETE','root_sha256':pending['last_installed_root'],'publication_attested':True,'message_id':'5b9c3aba-d130-4f5a-be5b-150c9400ff3c','published_at':'2026-10-24T09:38:55.987613+00:00','mission_complete_attested':False,'provider_calls':0,'count_calls':0,'generation_calls':0,'http_calls':0,'total_conservative_run_usd':0.4034139,'budget_usd':0.50,'editorial_quality':'NOT_ATTESTED','last_verified_successor_state':'ready','current_successor_state_verified':False,'native_PG_defense_accepted':True,'resume_claim_sqlstate':'57014','fresh_baseline_available':False,'generic_role_submission_count':20,'reachability_checked_at':'2026-10-24T10:24Z','reachability_probe_succeeded':False,'connection_error_code':'CONNECTION_TIMEOUT','read_performance_applied':False,'read_performance_installable':False}
 assert current['root_sha256']==pending['last_installed_root'] and current['mission_complete_attested'] is False
 allowed={'pending_read_performance_proposals','runtime_delivery_observations','current_runtime'}
 for obj in seeds.values():
  item=pending if obj is seeds[NAMES[0]] else {k:pending[k]for k in ['schema_version','release_key','status','live_baseline','last_installed_root','current_edge_version','current_UI_commit','candidate_scope','provider_calls','runtime']}
  rows=list(obj.get('pending_read_performance_proposals',[]));old=next((x for x in rows if x['release_key']==item['release_key']),None)
  if old is not None:assert old==item,'Pending source changed'
  else:rows.append(item)
  obj['pending_read_performance_proposals']=rows;history=list(obj.get('runtime_delivery_observations',[]))
  for value in [obj['current_runtime'],current]:
   if value not in history:history.append(value)
  obj['runtime_delivery_observations']=history;obj['current_runtime']=current
 for n in NAMES:
  before=read(C/n)
  for k,v in before.items():
   if k not in allowed:assert seeds[n][k]==v,'Installed field altered: '+k
  assert ref(C/n)==before_refs[n],'Input delivery drift'
 O.mkdir(exist_ok=True)
 for n in NAMES:(O/n).write_text(json.dumps(seeds[n],ensure_ascii=False,indent=2)+'\n')
 shutil.copyfile(C/ROOT,O/ROOT)
 result={'ready':True,'scope':'Private delivery ready; performance proposal NOT_INSTALLABLE/NOT_APPLIED, current server performance not qualified','performance_candidate_installable':False,'performance_candidate_applied':False,'files':[ref(O/n) for n in NAMES+[ROOT]],'runtime':current,'script':ref(Path(__file__))};(O/'PACKAGE_READY.json').write_text(json.dumps(result,indent=2)+'\n');return result
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--input-dir',type=Path);p.add_argument('--runtime-proof',type=Path);a=p.parse_args();print(json.dumps(build(a.input_dir,a.runtime_proof),ensure_ascii=False))

