-- Root metadata-only UI ready observer handoff. No DB bodies/DDL/Edge/game data/provider.
BEGIN;SET LOCAL search_path TO pg_catalog,public,extensions;SET LOCAL lock_timeout='5s';SET LOCAL statement_timeout='60s';
DO $usd_install$
DECLARE actual jsonb;expected jsonb;newpre jsonb;before_extra jsonb;after_extra jsonb;root_text text;root_sha text;n integer;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('C1266:GENERIC-AI:AVAILABILITY',0));
 PERFORM 1 FROM mission_generic_owner.role_window_cursors WHERE master_session_id='44078c5f-7001-4129-9506-e2f34e68c8ac'::uuid FOR UPDATE;
 PERFORM public.master_v2_lock_scope('44078c5f-7001-4129-9506-e2f34e68c8ac'::uuid);
 PERFORM 1 FROM mission_factory_owner.editor_release_readiness WHERE singleton FOR UPDATE;
 PERFORM 1 FROM mission_factory_owner.c464_control WHERE singleton FOR UPDATE;
 PERFORM 1 FROM mission_factory_owner.provider_authoring_runtime WHERE singleton FOR UPDATE;
 PERFORM 1 FROM mission_generic_owner.runtime_policy WHERE singleton FOR UPDATE;
 PERFORM 1 FROM mission_generic_owner.provider_policy WHERE singleton FOR UPDATE;
 PERFORM 1 FROM mission_generic_owner.flow_runtime_gate WHERE singleton FOR UPDATE;
 PERFORM 1 FROM mission_generic_owner.dispatch_admissions WHERE master_session_id='44078c5f-7001-4129-9506-e2f34e68c8ac'::uuid FOR UPDATE;
 PERFORM 1 FROM mission_factory_owner.provider_authoring_admissions ORDER BY actor_user FOR UPDATE;
 IF (NOT EXISTS(SELECT 1 FROM mission_generic_owner.work_items WHERE state IN('claimed','authorized','provider_started')) AND NOT EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_attempts WHERE status IN('reserved','authorized','provider_started')) AND NOT EXISTS(SELECT 1 FROM mission_generic_owner.work_items WHERE master_session_id='44078c5f-7001-4129-9506-e2f34e68c8ac'::uuid AND (state IN('claimed','authorized','provider_started','uncertain') OR state='ready' AND id<>'2abb54cd-2460-e628-7c30-e76111803510'::uuid)) AND EXISTS(SELECT 1 FROM mission_generic_owner.work_items WHERE id='2abb54cd-2460-e628-7c30-e76111803510'::uuid AND state='ready' AND authorization_id IS NULL AND dispatch_id IS NULL AND finalized_at IS NULL)) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'READY_HANDOFF_ACTIVE' USING ERRCODE='P0001';END IF;
