consumer_refs={n:ref(str(A/n)) for n in ['AUTHOR.json','CLIENT_READY.json','STATIC.json','CONTRACT.json','CLIENT.diff','BUILD_CANDIDATE.py','CHECK.py','SOURCE_REVIEW_PACKET.json']}
recipe={'schema_version':'mission-ready-observer-handoff-recipe/1','baseline_root':root,'builder':ref('BUILD_INTEGRATED.py'),'checker':ref('POSTFLIGHT_CHECK.py'),'static':ref('AUTHOR_STATIC.json'),'baseline_query':ref('BASELINE.sql'),'extra_query':ref('EXTRA.sql'),'baseline_db':ref('DB_BEFORE.json'),'baseline_scene':ref('EXTRA_BEFORE.json'),'baseline_edge':ref('EDGE_BEFORE.json'),'git_before':ref('GIT_BEFORE.json'),'author_directory':ref('AUTHOR_DIR.json'),'consumer_refs':consumer_refs,'expected_UI_files':client['files'],'UI_build':client['build_marker'],'db_bodies_changed':0,'new_objects':0,'Edge_unchanged':old['edge_bundles'],'protected':48,'provider_calls':0,'ready_work_exception':'Only exactREADY2abb54cd-2460-e628-7c30-e76111803510 immutable; all other active/provider absent','rollout':'source review -> UI2Git/domain actual -> bind -> materialreview -> freshbaseline exact -> Rootmetadata only -> explicitnormalStaffresume','runtime':'NOT_RUN','history':'same request cumulative deroga5 preserved, noreset'}
mode=sys.argv[1]if len(sys.argv)>1 else'prepare'
