assert recipe==read('RECIPE.json');review=read('INTEGRATED_REVIEW.json');assert review['findings_count']=={'P0':0,'P1':0,'P2':0};assert ref('RECIPE.json')['sha256']in canon(review) and ref('BUILD_INTEGRATED.py')['sha256']in canon(review)
pub=read('CLIENT_PUBLICATION.json');assert pub['previous_head']==git['commit'] and pub['domain_verified']is True and pub.get('build',pub.get('build_marker'))==client['build_marker'] and len(pub['files'])==2
new=copy.deepcopy(old);new['ui']['git_head']=pub['commit'];new['ui']['verified']=True
for f in client['files']:
 v=next(v for v in pub['files']if v['name']==f['name']);assert v['bytes']==f['bytes'] and v['sha256']==f['sha256'] and re.fullmatch('[0-9a-f]{40}',v['blob']);new['ui']['files'][f['name']]={'bytes':v['bytes'],'sha256':v['sha256'],'git_blob':v['blob']}
key='c1266_ready_observer_handoff_proof';new['config'][key]={'schema_version':'mission-ready-observer-handoff-proof/1','recipe':ref('RECIPE.json'),'source_review':ref('INTEGRATED_REVIEW.json'),'previous_release_sha256':root,'provider_calls':0}
cfg=copy.deepcopy(new['config']);cfg.pop('sha256',None)
for k in ['c1266_clean_staff','c1266_staff_campaign']:
 for f in ['grant_id','not_before','expires_at']:cfg[k].pop(f,None)
cfg['c1266_opening'].pop('admission_not_before',None);new['config']['sha256']=sha(canon(cfg));new['contract']['code_identity_sha256']=sha(canon({'db':new['db_core']['sha256'],'edge':new['edge_bundles'],'UI':new['ui'],'config':new['config']['sha256']}))
assert new['db_core']==old['db_core'] and new['edge_bundles']==old['edge_bundles'] and new['recovery']==old['recovery'];save('EXPECTED_ROOT.json',new)
query=(P/'BASELINE.sql').read_text().strip().rstrip(';');extra=(P/'EXTRA.sql').read_text().strip().rstrip(';');expected={k:v for k,v in b.items()if k!='captured_at'}
inflight="NOT EXISTS(SELECT 1 FROM mission_generic_owner.work_items WHERE state IN('claimed','authorized','provider_started')) AND NOT EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_attempts WHERE status IN('reserved','authorized','provider_started')) AND NOT EXISTS(SELECT 1 FROM mission_generic_owner.work_items WHERE master_session_id='44078c5f-7001-4129-9506-e2f34e68c8ac'::uuid AND (state IN('claimed','authorized','provider_started','uncertain') OR state='ready' AND id<>'2abb54cd-2460-e628-7c30-e76111803510'::uuid)) AND EXISTS(SELECT 1 FROM mission_generic_owner.work_items WHERE id='2abb54cd-2460-e628-7c30-e76111803510'::uuid AND state='ready' AND authorization_id IS NULL AND dispatch_id IS NULL AND finalized_at IS NULL)"
s="""-- Root metadata-only UI ready observer handoff. No DB bodies/DDL/Edge/game data/provider.
BEGIN;SET LOCAL search_path TO pg_catalog,public,extensions;SET LOCAL lock_timeout='5s';SET LOCAL statement_timeout='60s';
DO $usd_install$
DECLARE actual jsonb;expected jsonb;newpre jsonb;before_extra jsonb;after_extra jsonb;root_text text;root_sha text;n integer;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('C1266:GENERIC-AI:AVAILABILITY',0));
 PERFORM 1 FROM mission_generic_owner.role_window_cursors WHERE master_session_id='44078c5f-7001-4129-9506-e2f34e68c8ac'::uuid FOR UPDATE;
 PERFORM public.master_v2_lock_scope('44078c5f-7001-4129-9506-e2f34e68c8ac'::uuid);
"""
for t in ['mission_factory_owner.editor_release_readiness','mission_factory_owner.c464_control','mission_factory_owner.provider_authoring_runtime','mission_generic_owner.runtime_policy','mission_generic_owner.provider_policy','mission_generic_owner.flow_runtime_gate']:s+=' PERFORM 1 FROM '+t+' WHERE singleton FOR UPDATE;\n'
s+=" PERFORM 1 FROM mission_generic_owner.dispatch_admissions WHERE master_session_id='44078c5f-7001-4129-9506-e2f34e68c8ac'::uuid FOR UPDATE;\n PERFORM 1 FROM mission_factory_owner.provider_authoring_admissions ORDER BY actor_user FOR UPDATE;\n"+guard(inflight,'READY_HANDOFF_ACTIVE')
s+=' EXECUTE '+q(query)+' INTO actual;expected:='+q(expected)+'::jsonb;\n'+guard("(actual-'captured_at')=expected",'READY_HANDOFF_BASELINE_DRIFT')+' EXECUTE '+q(extra)+' INTO before_extra;\n'+guard('before_extra='+q(E)+'::jsonb','READY_HANDOFF_SCENE_DRIFT')+' newpre:='+q(new)+'::jsonb;\n'
s+=" root_text:=newpre::text;\n"+guard('octet_length(root_text)<=262144','READY_HANDOFF_ROOT_SIZE')+" root_sha:=encode(extensions.digest(convert_to(root_text,'UTF8'),'sha256'),'hex');\n"
s+=" UPDATE mission_factory_owner.editor_release_readiness SET canonical_preimage=root_text,revision_sha256=root_sha,observed_revision_sha256=root_sha,client_build='mission-factory-admin/2:'||root_sha,updated_at=clock_timestamp() WHERE singleton AND revision_sha256="+q(root)+';\n GET DIAGNOSTICS n=ROW_COUNT;\n'+guard('n=1','READY_HANDOFF_ROOT_CAS')
s+=' UPDATE mission_factory_owner.c464_control SET release_sha256=root_sha WHERE singleton;\n GET DIAGNOSTICS n=ROW_COUNT;\n'+guard('n=1','READY_HANDOFF_G2_CAS')
s+=' UPDATE mission_factory_owner.provider_authoring_admissions SET release_sha256=root_sha WHERE actor_user IN('+','.join(q(a['actor_user'])for a in b['admissions'])+');\n GET DIAGNOSTICS n=ROW_COUNT;\n'+guard('n='+str(len(b['admissions'])),'READY_HANDOFF_ADMISSIONS_CAS')
for path,expr in [('{root,canonical_preimage}','to_jsonb(root_text)'),('{root,revision_sha256}','to_jsonb(root_sha)'),('{root,observed_revision_sha256}','to_jsonb(root_sha)'),('{root,client_build}',"to_jsonb('mission-factory-admin/2:'||root_sha)"),('{g2,release_sha256}','to_jsonb(root_sha)')]:s+=' expected:=jsonb_set(expected,'+q(path)+','+expr+');\n'
for i in range(len(b['admissions'])):s+=' expected:=jsonb_set(expected,'+q('{admissions,'+str(i)+',release_sha256}')+',to_jsonb(root_sha));\n'
s+=' EXECUTE '+q(query)+' INTO actual;\n'+guard("((actual-'captured_at') #- '{root,updated_at}')=(expected #- '{root,updated_at}')",'READY_HANDOFF_ONLY_METADATA_DIFF')+' EXECUTE '+q(extra)+' INTO after_extra;\n'+guard('after_extra=before_extra','READY_HANDOFF_SCENE_KEEP')+guard(inflight,'READY_HANDOFF_ACTIVE_AFTER')+"END $usd_install$;NOTIFY pgrst,'reload schema';COMMIT;\n"
(P/'INSTALL.sql').write_text(s);save('BOUND_MANIFEST.json',{'recipe':ref('RECIPE.json'),'builder':ref('BUILD_INTEGRATED.py'),'review':ref('INTEGRATED_REVIEW.json'),'installer':ref('INSTALL.sql'),'UI_publication':ref('CLIENT_PUBLICATION.json'),'db_bodies_changed':0,'new_objects':0,'Edge_changes':0,'provider_calls':0});print(canon({'installer':ref('INSTALL.sql'),'status':'BOUND_AWAITING_MATERIAL_REVIEW'}))

