CREATE OR REPLACE FUNCTION mission_generic_owner.c1266_provider_input_v1(p_work uuid, p_limits jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE w mission_generic_owner.work_items; b mission_generic_owner.run_bindings;
 a mission_generic_owner.dispatch_admissions; authority jsonb; admission jsonb;
 snapshot jsonb; narrative jsonb;scope jsonb;max_input integer;max_request integer;continuation6 jsonb;
 scene_policy_cached jsonb;scene_policy_final jsonb;
BEGIN
 SELECT * INTO STRICT w FROM mission_generic_owner.work_items WHERE id=p_work;
 authority:=mission_generic_owner.c1266_execution_authority_v1(w.master_session_id,false,true);
 IF authority IS NULL OR authority->>'runtime_authorized' IS DISTINCT FROM 'true'
 THEN RAISE EXCEPTION 'C1266_PROVIDER5_RUNTIME_AUTHORITY_REQUIRED' USING ERRCODE='42501';END IF;
 SELECT * INTO STRICT b FROM mission_generic_owner.run_bindings WHERE master_session_id=w.master_session_id;
 SELECT * INTO STRICT a FROM mission_generic_owner.dispatch_admissions WHERE master_session_id=w.master_session_id;
 snapshot:=mission_generic_owner.c8_policy_snapshot_v1(w.id);
 -- Reuse only the policy qualified by the original C8 builder in this invocation.
 scene_policy_cached:=snapshot->'scene_policy';
 IF scene_policy_cached IS NOT NULL AND (
  snapshot->>'schema_version' IS DISTINCT FROM 'c1266-staff-scene-count-snapshot/2'
  OR scene_policy_cached IS DISTINCT FROM '{"mode":"staff_scene_uncapped","maxCount":null,"maxGen":null,"maxHTTP":null,"maxUSD":null}'::jsonb
  OR snapshot->>'scene_policy_sha256' IS DISTINCT FROM public.combat_v2_sha256(scene_policy_cached)
  OR snapshot->>'scene_policy_contract_sha256' IS DISTINCT FROM '1564720ca33bc961ff26fc15e07bd364ebd41a60b7a5a48c970a9c100038fad6'
  OR snapshot->>'release_sha256' IS DISTINCT FROM authority->>'release_sha256')
 THEN RAISE EXCEPTION 'C1266_PROVIDER_POLICY_MEMO_BINDING' USING ERRCODE='P0001';END IF;
 narrative:=mission_public_owner.work_contract_v1(w.id);
 -- Historical contract bytes stay sealed. A current named continuation
 -- proves compatibility before selecting its original transport authority.
 IF narrative IS NOT NULL AND narrative->>'release_sha256' IS DISTINCT FROM authority->>'release_sha256' THEN
  continuation6:=CASE WHEN authority#>>'{admission,schema_version}'='c1266-staff-admission-authority/3'
   THEN mission_generic_owner.counted_resume_evidence_v1(w.id,w.lease_id)
   ELSE mission_generic_owner.c1266_opening_continuation_v1(w.id) END;
  IF continuation6 IS NULL AND authority#>>'{admission,schema_version}'='c1266-staff-admission-authority/3' THEN
   continuation6:=mission_generic_owner.native_reissue_continuation_v1(w.id);
  END IF;
  IF continuation6 IS NULL OR continuation6->>'current_release_sha256' IS DISTINCT FROM authority->>'release_sha256'
  OR continuation6->>'contract_sha256' IS DISTINCT FROM public.combat_v2_sha256(narrative)
  THEN RAISE EXCEPTION 'C1266_CONTINUATION_AUTHORITY_REQUIRED' USING ERRCODE='42501';END IF;
  authority:=jsonb_set(jsonb_set(authority,'{release_sha256}',narrative->'release_sha256'),'{admission}',narrative#>'{source_attestation,execution_authority,admission}');
 END IF;
 admission:=authority->'admission';
 IF (w.kind IN('choice','director','narration')) IS DISTINCT FROM TRUE OR w.payload_sha256 IS DISTINCT FROM public.combat_v2_sha256(w.payload)
  OR b.snapshot_sha256 IS DISTINCT FROM mission_internal.fingerprint(b.snapshot)
  OR w.definition_sha256 IS DISTINCT FROM b.snapshot_sha256
  OR a.enabled IS DISTINCT FROM TRUE OR a.c7_budget_enforced IS DISTINCT FROM TRUE
  OR a.call_limit IS DISTINCT FROM 14 OR a.cost_budget_usd IS DISTINCT FROM 0.3136
  OR a.c8_count_upper_cost_usd IS DISTINCT FROM 0.0124
  OR (a.c8_count_qualification_sha256 ~ '^[0-9a-f]{64}$') IS DISTINCT FROM TRUE
  OR authority->>'financial_qualification_sha256' IS DISTINCT FROM a.c8_count_qualification_sha256
  OR (authority->>'release_sha256' ~ '^[0-9a-f]{64}$') IS DISTINCT FROM TRUE
  OR snapshot->>'policy_version' IS DISTINCT FROM '2' OR snapshot->>'max_input_tokens' IS DISTINCT FROM '24000'
  OR snapshot->>'max_output_tokens' IS DISTINCT FROM '20000' OR snapshot->>'model' IS DISTINCT FROM 'gpt-6-luna'
  OR snapshot->>'reasoning_effort' IS DISTINCT FROM 'high' OR snapshot->>'store' IS DISTINCT FROM 'false'
  OR (snapshot->>'input_usd_million')::numeric IS DISTINCT FROM 0.1 OR (snapshot->>'output_usd_million')::numeric IS DISTINCT FROM 0.5
 THEN RAISE EXCEPTION 'C1266_PROVIDER5_WORK_POLICY_BINDING' USING ERRCODE='P0001';END IF;
 IF authority->>'execution_context'='staff_mission' AND admission->>'schema_version'='c1266-staff-admission-authority/3' THEN
  DECLARE mq jsonb:=mission_generic_owner.manual_staff_scope_v1(w.master_session_id);
  BEGIN
   IF mq IS NULL OR admission IS DISTINCT FROM jsonb_build_object('schema_version','c1266-staff-admission-authority/3','kind','staff_finite','resource_scope','staff_simulation','finite_admission_sha256',public.combat_v2_sha256(mq),'admission_id',mq->>'start_receipt_id','location_id',mq->>'location_id')
   OR scene_policy_cached IS NOT NULL THEN RAISE EXCEPTION 'MANUAL_STAFF_PROVIDER_ADMISSION' USING ERRCODE='42501';END IF;
  END;
 ELSIF authority->>'execution_context'='staff_mission' THEN
   IF (NOT mission_factory_owner.keys_exact_v2(admission,ARRAY['schema_version','kind','resource_scope','finite_admission_sha256','grant_id','not_before','expires_at','location_id'])
   OR admission->>'schema_version' IS DISTINCT FROM 'c1266-staff-admission-authority/1'
   OR admission->>'kind' IS DISTINCT FROM 'staff_finite' OR admission->>'resource_scope' IS DISTINCT FROM 'staff_simulation') AND NOT ((mission_factory_owner.keys_exact_v2(admission,ARRAY['schema_version','kind','resource_scope','finite_admission_sha256','grant_id','not_before','expires_at','location_id','campaign_id','time_policy']) AND admission->>'schema_version'='c1266-staff-admission-authority/2' AND admission->>'kind'='staff_finite' AND admission->>'resource_scope'='staff_simulation' AND admission->>'campaign_id'='b2fc5e28-072b-41f2-8dd8-cb5a35a13092' AND admission->>'grant_id'='b925043a-c1b3-434b-8fb4-f335903b2af0' AND admission->>'not_before'='2026-10-20T14:12:18.393948+00:00' AND admission->>'expires_at'='2026-10-20T15:12:18.393948+00:00' AND admission->>'location_id'='0b85f354-9cdb-47e1-baf9-3d266bb7e06b' AND admission->'time_policy'='{"mode":"budget_or_explicit_stop","expires_at_role":"historical_provenance"}'::jsonb AND (admission->>'finite_admission_sha256' ~ '^[a-f0-9]{64}$') IS TRUE) IS TRUE)
  THEN RAISE EXCEPTION 'C1266_PROVIDER5_STAFF_CLOSED8';END IF;
 ELSIF authority->>'execution_context'='ordinary_mission' THEN
  IF NOT mission_factory_owner.keys_exact_v2(admission,ARRAY['schema_version','kind','resource_scope','ordinary_admission_sha256','source_mission_id','source_plan_version_id','source_definition_id','source_plan_sha256','source_definition_sha256','source_sha256','location_id','start_receipt_id','roster_snapshot_sha256','eligibility_receipt_sha256','protection'])
   OR admission->>'schema_version' IS DISTINCT FROM 'c1266-ordinary-admission-authority/1'
   OR admission->>'kind' IS DISTINCT FROM 'ordinary_authenticated'
   OR (admission->>'resource_scope' IN('world','staff_simulation')) IS DISTINCT FROM TRUE
  THEN RAISE EXCEPTION 'C1266_PROVIDER5_ORDINARY_CLOSED15';END IF;
  IF admission->>'resource_scope'='world' THEN
   IF NOT mission_factory_owner.keys_exact_v2(admission->'protection',ARRAY['schema_version','kind'])
    OR admission#>>'{protection,schema_version}' IS DISTINCT FROM 'c1266-ordinary-protection/1'
    OR admission#>>'{protection,kind}' IS DISTINCT FROM 'world'
   THEN RAISE EXCEPTION 'C1266_PROVIDER5_WORLD_PROTECTION_CLOSED2';END IF;
  ELSE
   IF NOT mission_factory_owner.keys_exact_v2(admission->'protection',ARRAY['schema_version','kind','existing_qa_receipt_sha256','location_id','roster_snapshot_sha256'])
    OR admission#>>'{protection,schema_version}' IS DISTINCT FROM 'c1266-ordinary-protection/1'
    OR admission#>>'{protection,kind}' IS DISTINCT FROM 'existing_staff_simulation'
    OR (admission#>>'{protection,existing_qa_receipt_sha256}' ~ '^[0-9a-f]{64}$') IS DISTINCT FROM TRUE
    OR admission#>>'{protection,location_id}' IS DISTINCT FROM admission->>'location_id'
    OR admission#>>'{protection,roster_snapshot_sha256}' IS DISTINCT FROM admission->>'roster_snapshot_sha256'
   THEN RAISE EXCEPTION 'C1266_PROVIDER5_PROTECTED_ORDINARY_CLOSED5';END IF;
  END IF;
 ELSE RAISE EXCEPTION 'C1266_PROVIDER5_EXECUTION_CONTEXT' USING ERRCODE='42501';END IF;
 IF (narrative IS NULL AND w.kind IN('director','narration')) OR (narrative IS NOT NULL AND(
  narrative->>'schema_version' IS DISTINCT FROM 'mission-narrative-admission/3'
  OR narrative->>'master_session_id' IS DISTINCT FROM w.master_session_id::text
  OR narrative->>'work_id' IS DISTINCT FROM w.id::text
  OR narrative->>'release_sha256' IS DISTINCT FROM authority->>'release_sha256'))
 THEN RAISE EXCEPTION 'C1266_PROVIDER5_NARRATIVE_ADMISSION_REQUIRED' USING ERRCODE='42501';END IF;
 IF jsonb_typeof(p_limits) IS DISTINCT FROM 'object' OR jsonb_typeof(p_limits->'max_input_bytes') IS DISTINCT FROM 'number'
  OR jsonb_typeof(p_limits->'max_request_bytes') IS DISTINCT FROM 'number'
  OR p_limits->>'max_output_tokens' IS DISTINCT FROM '20000'
 THEN RAISE EXCEPTION 'C1266_PROVIDER5_BYTE_SHAPE' USING ERRCODE='22023';END IF;
 max_input:=(p_limits->>'max_input_bytes')::integer;max_request:=(p_limits->>'max_request_bytes')::integer;
 -- Conserva la differenza dei limiti di trasporto già presente nei due profili.
 IF max_input<=0 OR max_request<=0
  OR (mission_generic_owner.capacity()->>'input_capacity_bytes')::integer IS NULL
  OR max_input>(10*(CASE WHEN admission->>'kind'='staff_finite' THEN CASE WHEN w.kind='director' THEN 65536 ELSE 49152 END ELSE least(49152,(mission_generic_owner.capacity()->>'input_capacity_bytes')::integer) END))
  OR max_request>(10*(CASE WHEN admission->>'kind'='staff_finite' THEN CASE WHEN w.kind='director' AND authority->>'runtime_authorized'='true' AND authority->>'execution_context'='staff_mission' AND authority#>>'{admission,kind}'='staff_finite' AND authority#>>'{admission,resource_scope}'='staff_simulation' AND scene_policy_cached IS NOT NULL AND narrative->>'editorial_profile'='cinematic_master_1' THEN 98304 WHEN w.kind='narration' THEN 131072 ELSE 65536 END ELSE least(65536,(mission_generic_owner.capacity()->>'input_capacity_bytes')::integer) END))
 THEN RAISE EXCEPTION 'C1266_PROVIDER5_BYTE_BOUND' USING ERRCODE='22023';END IF;
 scope:=jsonb_build_object('schema_version','c1266-mission-work-scope/2','execution_context',authority->>'execution_context',
  'master_session_id',w.master_session_id,'work_id',w.id,'event_id',w.event_id,'request_key',w.request_key,'revision',w.revision,
  'authority_receipt_id',w.authority_receipt_id,'definition_sha256',w.definition_sha256,'payload_sha256',w.payload_sha256,
  'payload_schema_version',w.payload->>'schema_version','run_control_version',w.run_control_version,
  'narrative_admission_sha256',CASE WHEN narrative IS NOT NULL THEN public.combat_v2_sha256(narrative) END,'release_sha256',authority->>'release_sha256',
  'admission',admission,'policy_snapshot_sha256',public.combat_v2_sha256(snapshot),'financial_qualification_sha256',a.c8_count_qualification_sha256);
 -- Preserve the original live final validation, including every transitive guard.
 scene_policy_final:=mission_generic_owner.c1266_staff_scene_policy_v1(w.master_session_id);
 IF scene_policy_final IS DISTINCT FROM scene_policy_cached
 THEN RAISE EXCEPTION 'C1266_PROVIDER_POLICY_DRIFT' USING ERRCODE='P0001';END IF;
 IF scene_policy_cached IS NOT NULL THEN
 scope:=jsonb_set(scope,'{schema_version}','"c1266-mission-work-scope/3"'::jsonb)||jsonb_build_object('scene_policy',scene_policy_cached,'scene_policy_sha256',public.combat_v2_sha256(scene_policy_cached),'scene_policy_contract_sha256','1564720ca33bc961ff26fc15e07bd364ebd41a60b7a5a48c970a9c100038fad6');
 RETURN jsonb_build_object('schema_version','mission-generic-provider-input/6','input_tokens_limit',24000,'policy_version',2,'http_calls_per_generation',2,'scope',scope,'pricing',jsonb_build_object('model','gpt-6-luna','reasoning_effort','high','store',false,'max_output_tokens',20000,'input_usd_million',0.1,'output_usd_million',0.5,'count_upper_cost_usd','0.0124','generation_upper_cost_usd','0.0124'),'byte_bounds',jsonb_build_object('max_input_bytes',max_input,'max_request_bytes',max_request));END IF;
 RETURN jsonb_build_object('schema_version','mission-generic-provider-input/5','input_tokens_limit',24000,'policy_version',2,'http_calls_per_generation',2,
  'scope',scope,'pricing',jsonb_build_object('model','gpt-6-luna','reasoning_effort','high','store',false,'max_output_tokens',20000,
   'input_usd_million',0.1,'output_usd_million',0.5,'count_upper_cost_usd','0.0124','generation_upper_cost_usd','0.0124'),
  'byte_bounds',jsonb_build_object('max_input_bytes',max_input,'max_request_bytes',max_request));
END $function$

public.mission_generic_input_count_start.source:
CREATE OR REPLACE FUNCTION public.mission_generic_input_count_start_v1(p_work uuid, p_lease uuid, p_payload_text text, p_payload_sha text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE w mission_generic_owner.work_items;r mission_narrative_internal.dispatch_receipts;a mission_generic_owner.dispatch_admissions;pol mission_narrative_internal.runtime_policy;payload jsonb;projection jsonb;snap jsonb;details jsonb;old_details jsonb;measurement uuid:=gen_random_uuid();request_limit integer;count_quota jsonb;count_ticket uuid;count_staff boolean;c5_proof jsonb;campaign_budget jsonb;campaign_proof jsonb;
BEGIN
 perform mission_ai_board_owner.service_only();
 -- C1266_AVAILABILITY_COORD: shared before mutation locks; xact lifetime.
 PERFORM pg_catalog.pg_advisory_xact_lock_shared(pg_catalog.hashtextextended('C1266:GENERIC-AI:AVAILABILITY',0));

 -- C9: freeze policy DML through proof, Native reserve and authorization.
 LOCK TABLE mission_narrative_internal.runtime_policy IN SHARE MODE;
 select * into strict pol from mission_narrative_internal.runtime_policy where singleton;

 -- Same scene-before-work order as Native claim/authorize.
 perform 1 from mission_generic_owner.role_window_cursors where master_session_id=(select master_session_id from mission_generic_owner.work_items where id=p_work) for update;
 perform 1 from public.master_v2_sessions where id=(select master_session_id from mission_generic_owner.work_items where id=p_work) for update; select * into strict w from mission_generic_owner.work_items where id=p_work for update;
 select * into strict a from mission_generic_owner.dispatch_admissions where master_session_id=w.master_session_id for update;
 select * into strict r from mission_narrative_internal.dispatch_receipts where id=w.dispatch_receipt_id for update;
 IF w.id='48e1bdcd-f044-be8c-1923-54d38e7e822c'::uuid AND (mission_generic_owner.c8_context24_scope_v1(w.id) IS DISTINCT FROM TRUE OR mission_generic_owner.c726_factory_staff_runtime_v1(w.master_session_id) IS DISTINCT FROM TRUE) THEN RAISE EXCEPTION 'C889_CONTEXT24_RUNTIME_CLOSED' USING ERRCODE='42501';END IF;
 IF EXISTS(SELECT 1 FROM mission_generic_owner.manual_staff_admissions_v1 ma WHERE ma.master_session_id=w.master_session_id) THEN
  DECLARE manual_q jsonb:=mission_generic_owner.manual_staff_scope_v1(w.master_session_id);
          manual_sealed jsonb:=mission_generic_owner.c1266_historical_work_v1(w.id);
  BEGIN
   c5_proof:=mission_generic_owner.c1266_execution_authority_v1(w.master_session_id,false,true);
   IF manual_q IS NULL OR c5_proof IS NULL OR c5_proof->>'runtime_authorized' IS DISTINCT FROM 'true'
    OR c5_proof->>'execution_context' IS DISTINCT FROM 'staff_mission'
    OR c5_proof->'admission' IS DISTINCT FROM jsonb_build_object('schema_version','c1266-staff-admission-authority/3','kind','staff_finite','resource_scope','staff_simulation','finite_admission_sha256',public.combat_v2_sha256(manual_q),'admission_id',manual_q->>'start_receipt_id','location_id',manual_q->>'location_id')
    OR a.c7_budget_qualification_sha256 IS DISTINCT FROM manual_q->>'budget_qualification_sha256'
    OR manual_sealed IS NULL OR manual_sealed->>'schema_version' IS DISTINCT FROM 'c1266-work-execution-attestation/3'
    OR manual_sealed->'admission' IS DISTINCT FROM c5_proof->'admission'
    OR (manual_sealed->>'release_sha256' IS DISTINCT FROM c5_proof->>'release_sha256' AND (
     mission_generic_owner.native_reissue_continuation_v1(w.id)->>'current_release_sha256' IS DISTINCT FROM c5_proof->>'release_sha256'))
    OR manual_sealed->>'binding_sha256' IS DISTINCT FROM c5_proof->>'binding_sha256'
    OR manual_sealed->>'financial_qualification_sha256' IS DISTINCT FROM c5_proof->>'financial_qualification_sha256'
    OR manual_sealed->>'c7_budget_qualification_sha256' IS DISTINCT FROM c5_proof->>'c7_budget_qualification_sha256'
   THEN RAISE EXCEPTION 'MANUAL_STAFF_COUNT_INPUT_PROOF_REQUIRED' USING ERRCODE='42501';END IF;
  END;
 ELSIF EXISTS(SELECT 1 FROM mission_generic_owner.dispatch_admissions ad JOIN mission_factory_owner.editor_release_readiness rr ON rr.singleton
 WHERE ad.master_session_id=w.master_session_id
 AND ad.c7_budget_qualification_sha256=rr.canonical_preimage::jsonb#>>'{config,c1266_clean_staff,c7_budget_qualification_sha256}')
 AND (mission_generic_owner.c8_context24_scope_v1(w.id) IS DISTINCT FROM TRUE
 OR mission_generic_owner.c1266_clean_staff_admission_v1(w.master_session_id,true,true) IS NULL)
 THEN RAISE EXCEPTION 'C1266_CLEAN_INPUT_PROOF_REQUIRED' USING ERRCODE='42501';END IF;
 IF mission_generic_owner.c1266_opening_named_v1(w.master_session_id) THEN
  IF c5_proof IS NULL THEN c5_proof:=mission_generic_owner.c1266_execution_authority_v1(w.master_session_id,false,true);END IF;
  IF c5_proof IS NULL OR mission_generic_owner.flow_scope_enabled(w.master_session_id) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'C1266_COUNT5_CLOSED' USING ERRCODE='42501';END IF;
 END IF;
 pol.max_input_tokens:=(mission_generic_owner.c8_policy_snapshot_v1(w.id)->>'max_input_tokens')::integer;
 perform mission_generic_owner.work_assert(w);perform mission_generic_owner.role_dispatch_assert_v4(w.id);perform mission_generic_owner.assert_runtime(w.master_session_id);perform mission_generic_owner.provider_ready(w.id);
 IF EXISTS(SELECT 1 FROM public.master_v2_sessions s726 WHERE s726.id=w.master_session_id AND s726.owner_kind='ai_service' AND s726.location_id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid AND (EXISTS(SELECT 1 FROM mission_generic_owner.flow_staff_sessions f726 WHERE f726.master_session_id=s726.id AND f726.enabled) OR EXISTS(SELECT 1 FROM mission_factory_owner.quest_run_sources q726 WHERE q726.session_id=s726.id AND q726.availability_scope='staff' AND q726.execution_context='staff_simulation'))) AND NOT mission_academy_owner.staff_carrier_runtime(w.master_session_id) AND NOT mission_generic_owner.c726_factory_staff_runtime_v1(w.master_session_id) THEN RAISE EXCEPTION 'C726_FACTORY_STAFF_SCOPE_CLOSED' USING ERRCODE='42501';END IF;

 if not a.c7_budget_enforced or a.c8_count_upper_cost_usd is null or a.c8_count_qualification_sha256 is null then raise exception 'C8_COUNT_TARIFF_UNQUALIFIED' using errcode='55000';end if;
 if w.state<>'claimed' or w.lease_id is distinct from p_lease or w.lease_expires_at<=clock_timestamp() or r.status<>'claimed' or r.authority_receipt_id<>w.id or r.master_session_id<>w.master_session_id or r.request_key<>w.request_key or r.event_kind<>'mission_generic_event' or r.renderer_version<>'mission-generic-runtime/1' or r.dispatch_count<>0 or w.authorization_id is not null or w.dispatch_id is not null or exists(select 1 from mission_narrative_internal.dispatch_attempts where receipt_id=r.id) or exists(select 1 from mission_narrative_internal.provider_authorizations where receipt_id=r.id) then raise exception 'C8_COUNT_SCOPE' using ERRCODE='P0001';end if;
 if p_payload_text is null or p_payload_sha !~ '^[0-9a-f]{64}$' or p_payload_sha is distinct from encode(extensions.digest(convert_to(p_payload_text,'UTF8'),'sha256'),'hex') then raise exception 'C8_COUNT_REQUEST_HASH' using errcode='22023';end if;
 payload:=p_payload_text::jsonb;
 request_limit:=case when w.kind='narration' and (mission_academy_owner.staff_carrier_runtime(w.master_session_id) OR mission_generic_owner.c726_factory_staff_runtime_v1(w.master_session_id)) then 131072 when w.kind='director' and (mission_academy_owner.staff_carrier_runtime(w.master_session_id) OR mission_generic_owner.c726_factory_staff_runtime_v1(w.master_session_id)) then 65536 else least(65536,(mission_generic_owner.capacity()->>'input_capacity_bytes')::integer) end;
  IF w.kind='director' AND c5_proof->>'runtime_authorized'='true' AND c5_proof->>'execution_context'='staff_mission' AND c5_proof#>>'{admission,kind}'='staff_finite' AND c5_proof#>>'{admission,resource_scope}'='staff_simulation' AND mission_generic_owner.c1266_staff_scene_policy_v1(w.master_session_id) IS NOT NULL AND (mission_public_owner.work_contract_v1(w.id))->>'editorial_profile'='cinematic_master_1' THEN request_limit:=98304;END IF;
 -- Count validates the same tenfold full-request byte bound; token snapshot unchanged.
 request_limit:=request_limit*10;
 if octet_length(p_payload_text)>request_limit or not(payload ?& array['model','input','reasoning','text','store','max_output_tokens']) or payload-'model'-'input'-'reasoning'-'text'-'store'-'max_output_tokens'<>'{}'::jsonb or payload->>'model' is distinct from pol.model or payload->'reasoning' is distinct from jsonb_build_object('effort',pol.reasoning_effort) or payload->'store' is distinct from 'false'::jsonb or payload->'max_output_tokens' is distinct from to_jsonb(pol.max_output_tokens) or jsonb_typeof(payload->'input')<>'array' or jsonb_typeof(payload->'text')<>'object' then raise exception 'C8_COUNT_REQUEST_POLICY' using errcode='22023';end if;
 snap:=mission_generic_owner.c8_policy_snapshot_v1(w.id);projection:=payload-'store'-'max_output_tokens';
 select da.details into old_details from mission_narrative_internal.dispatch_audit da where da.receipt_id=r.id and da.event_code='c8_count_started';
 if found then
  if old_details->>'generation_request_sha256' is distinct from p_payload_sha or old_details->>'lease_id' is distinct from p_lease::text then raise exception 'C8_COUNT_REPLAY_CONFLICT' using ERRCODE='P0001';end if;
  return jsonb_build_object('schema_version','mission-generic-count-start/1','work_id',w.id,'measurement_id',old_details->>'measurement_id','granted_now',false,'generation_request_sha256',p_payload_sha,'count_request_sha256',old_details->>'count_request_sha256','model',old_details#>>'{policy_snapshot,model}','policy_version',(old_details#>>'{policy_snapshot,policy_version}')::integer,'max_input_tokens',(old_details#>>'{policy_snapshot,max_input_tokens}')::integer,'max_output_tokens',(old_details#>>'{policy_snapshot,max_output_tokens}')::integer,'policy_snapshot_sha256',old_details->>'policy_snapshot_sha256','count_http_calls',1,'generation_http_calls',0);
 end if;
 campaign_budget:=mission_generic_owner.c7_run_budget_v1(w.master_session_id,true,w.id);
 IF campaign_budget ? 'campaign_provider_deadline' THEN
  PERFORM 1 FROM staff_ai_quota_private.runtime WHERE singleton FOR UPDATE;
  campaign_budget:=mission_generic_owner.c7_run_budget_v1(w.master_session_id,true,w.id);
 END IF;
 IF campaign_budget->>'allowed'='false' THEN
  IF campaign_budget->>'reason_code' IN('C1266_CAMPAIGN_LIMIT_STOP','C1266_CAMPAIGN_POLICY_CLOSED')
   AND campaign_budget->>'campaign_id' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   AND campaign_budget->>'campaign_policy_sha256' ~ '^[0-9a-f]{64}$' THEN
   campaign_proof:=jsonb_build_object('schema_version','c1266-campaign-count-no-http/1','work_id',w.id,
    'lease_id',p_lease,'generation_request_sha256',p_payload_sha,
    'campaign_id',campaign_budget->>'campaign_id','campaign_policy_sha256',campaign_budget->>'campaign_policy_sha256',
    'reason_code',campaign_budget->>'reason_code');
   INSERT INTO mission_narrative_internal.dispatch_audit(receipt_id,event_code,details)
    SELECT r.id,'c18_campaign_count_denied_no_http',campaign_proof||jsonb_build_object('stop_causes',campaign_budget->'stop_causes','boundary','count_start')
    WHERE NOT EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_audit da
     WHERE da.receipt_id=r.id AND da.event_code='c18_campaign_count_denied_no_http' AND da.details->>'lease_id'=w.lease_id::text AND da.details->>'generation_request_sha256'=p_payload_sha);
   RETURN jsonb_build_object('schema_version','c1266-campaign-count-denied/1','work_id',w.id,'granted_now',false,
    'count_http_calls',0,'generation_http_calls',0,'campaign_no_http_proof',campaign_proof);
  END IF;
  RAISE EXCEPTION 'MGPG_C7_RUN_BUDGET_STOP' USING ERRCODE='55000';
 END IF;
 PERFORM mission_generic_owner.c758_ordinary_budget_assert_v1(w.master_session_id,w.id);
 count_staff:=(mission_academy_owner.staff_carrier_runtime(w.master_session_id) OR mission_generic_owner.c726_factory_staff_runtime_v1(w.master_session_id) OR mission_generic_owner.c758_admission_proof_v1(w.master_session_id));
 if count_staff then
  count_quota:=staff_ai_quota_private.reserve('mission_generic_ai',r.id,2,w.master_session_id,pol.model,a.c8_count_upper_cost_usd);
  if count_quota->>'granted_now' IS DISTINCT FROM 'true' OR count_quota->>'state' IS DISTINCT FROM 'reserved' OR count_quota->>'may_send_http' IS DISTINCT FROM 'false' OR coalesce(count_quota->>'call_id','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then raise exception 'C748_COUNT_QUOTA_FRESH_RESERVATION_REQUIRED' using errcode='55000';end if;
  count_ticket:=(count_quota->>'call_id')::uuid;count_quota:=staff_ai_quota_private.mark_sent(count_ticket);
  if count_quota->>'may_send_http' IS DISTINCT FROM 'true' OR count_quota->>'state' IS DISTINCT FROM 'sent' OR count_quota->>'call_id' IS DISTINCT FROM count_ticket::text then raise exception 'C748_COUNT_QUOTA_SENT_NO_HTTP' using errcode='55000';end if;
 end if;
 details:=jsonb_build_object('work_id',w.id,'lease_id',p_lease,'measurement_id',measurement,'generation_request_sha256',p_payload_sha,'generation_request_bytes',octet_length(p_payload_text),'generation_request_text',p_payload_text,'count_projection',projection,'count_request_sha256',public.combat_v2_sha256(projection),'policy_snapshot',snap,'policy_snapshot_sha256',public.combat_v2_sha256(snap),'count_upper_cost_usd',a.c8_count_upper_cost_usd,'count_qualification_sha256',a.c8_count_qualification_sha256,'count_http_calls_reserved',1,'generation_http_calls_reserved',1,'shared_count_ticket',count_ticket,'shared_count_scope',w.master_session_id,'shared_count_source',r.id,'shared_count_call_no',CASE WHEN count_staff THEN 2 ELSE NULL END);
 IF c5_proof IS NOT NULL THEN details:=details||jsonb_build_object('provider_input_contract_version',CASE WHEN mission_generic_owner.c1266_staff_scene_policy_v1(w.master_session_id) IS NOT NULL THEN 'mission-generic-provider-input/6' ELSE 'mission-generic-provider-input/5' END,'execution_context',c5_proof->>'execution_context','admission_sha256',public.combat_v2_sha256(c5_proof->'admission'),'c7_budget_qualification_sha256',c5_proof->>'c7_budget_qualification_sha256');END IF;
 insert into mission_narrative_internal.dispatch_audit(receipt_id,event_code,details) values(r.id,'c8_count_started',details);
 return jsonb_build_object('schema_version','mission-generic-count-start/1','work_id',w.id,'measurement_id',measurement,'granted_now',true,'generation_request_sha256',p_payload_sha,'count_request_sha256',public.combat_v2_sha256(projection),'model',pol.model,'policy_version',pol.policy_version,'max_input_tokens',pol.max_input_tokens,'max_output_tokens',pol.max_output_tokens,'policy_snapshot_sha256',public.combat_v2_sha256(snap),'count_http_calls',0,'generation_http_calls',0);
END $function$

mission_generic_owner.native_reissue_con.source:
CREATE OR REPLACE FUNCTION mission_generic_owner.native_reissue_continuation_v1(p_work uuid)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path TO '' AS $function$
DECLARE w mission_generic_owner.work_items;wc mission_public_owner.work_contracts_v1;
 current_authority jsonb;historical jsonb;evidence jsonb;link jsonb;n integer;original_id uuid;actor_id uuid;
BEGIN
 SELECT * INTO w FROM mission_generic_owner.work_items WHERE id=p_work;
 IF NOT FOUND OR w.kind IS DISTINCT FROM 'narration'
  OR w.payload->>'schema_version' IS DISTINCT FROM 'mission-generic-narration/3'
  OR w.payload_sha256 IS DISTINCT FROM public.combat_v2_sha256(w.payload) THEN RETURN NULL;END IF;
 SELECT * INTO wc FROM mission_public_owner.work_contracts_v1 WHERE work_id=w.id;
 IF NOT FOUND OR wc.contract_sha256 IS DISTINCT FROM public.combat_v2_sha256(wc.contract)
  OR wc.contract->>'schema_version' IS DISTINCT FROM 'mission-narrative-admission/3'
  OR wc.contract->>'work_id' IS DISTINCT FROM w.id::text
  OR wc.contract->>'master_session_id' IS DISTINCT FROM w.master_session_id::text
  OR wc.contract->>'release_sha256' IS DISTINCT FROM wc.release_sha256
  OR (wc.contract->'features' ?& ARRAY['unified_narration_v3','execution_authority_v1','combat_snapshot_origin_budget_v1']) IS DISTINCT FROM true THEN RETURN NULL;END IF;
 current_authority:=mission_generic_owner.c1266_execution_authority_v1(w.master_session_id,false,true);
 historical:=mission_generic_owner.c1266_historical_work_v1(w.id);
 IF current_authority IS NULL OR historical IS NULL
  OR current_authority->>'runtime_authorized' IS DISTINCT FROM 'true'
  OR current_authority->>'execution_context' IS DISTINCT FROM 'staff_mission'
  OR current_authority#>>'{admission,schema_version}' IS DISTINCT FROM 'c1266-staff-admission-authority/3'
  OR historical->>'schema_version' IS DISTINCT FROM 'c1266-work-execution-attestation/3'
  OR historical IS DISTINCT FROM wc.contract#>'{source_attestation,execution_authority}'
  OR historical->>'release_sha256' IS DISTINCT FROM wc.release_sha256
  OR historical->>'execution_context' IS DISTINCT FROM current_authority->>'execution_context'
  OR historical->'admission' IS DISTINCT FROM current_authority->'admission'
  OR historical->>'binding_sha256' IS DISTINCT FROM current_authority->>'binding_sha256'
  OR historical->>'financial_qualification_sha256' IS DISTINCT FROM current_authority->>'financial_qualification_sha256'
  OR historical->>'c7_budget_qualification_sha256' IS DISTINCT FROM current_authority->>'c7_budget_qualification_sha256'
  OR (current_authority->>'release_sha256' ~ '^[0-9a-f]{64}$') IS DISTINCT FROM true THEN RETURN NULL;END IF;
 SELECT count(*),jsonb_agg(jsonb_build_object('original_id',original_work.id,'actor_id',a.details->>'actor_user_id'))->0 INTO n,link
 FROM mission_narrative_internal.dispatch_audit a
 JOIN mission_generic_owner.work_items original_work ON original_work.dispatch_receipt_id=a.receipt_id
  AND original_work.master_session_id=w.master_session_id
 WHERE a.event_code='staff_combat_narration_preprovider_reissued'
  AND a.details->>'failed_work_id'=original_work.id::text
  AND a.details->>'successor_work_id'=w.id::text;
 IF n<>1 OR (link->>'actor_id' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$') IS DISTINCT FROM true THEN RETURN NULL;END IF;
 original_id:=(link->>'original_id')::uuid;actor_id:=(link->>'actor_id')::uuid;
 evidence:=mission_generic_owner.combat_narration_reissue_proof_v1(original_id,actor_id);
 IF evidence IS NULL OR evidence->>'schema_version' IS DISTINCT FROM 'mission-combat-narration-reissue-proof/1'
  OR evidence->>'master_session_id' IS DISTINCT FROM w.master_session_id::text
  OR evidence->>'failed_work_id' IS DISTINCT FROM original_id::text
  OR evidence->>'successor_work_id' IS DISTINCT FROM w.id::text
  OR evidence->>'batch_id' IS DISTINCT FROM w.authority_receipt_id::text
  OR evidence->>'payload_sha256' IS DISTINCT FROM w.payload_sha256
  OR evidence->>'owned_by_me' IS DISTINCT FROM 'true'
  OR (evidence->>'audit_sha256' ~ '^[0-9a-f]{64}$') IS DISTINCT FROM true THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('schema_version','mission-native-reissue-continuation/1','work_id',w.id,'master_session_id',w.master_session_id,
  'original_work_id',original_id,'contract_sha256',wc.contract_sha256,'contract_release_sha256',wc.release_sha256,
  'current_release_sha256',current_authority->>'release_sha256','payload_sha256',w.payload_sha256,'reissue_audit_sha256',evidence->>'audit_sha256');
END $function$;
ALTER FUNCTION mission_generic_owner.native_reissue_continuation_v1(uuid) OWNER TO postgres;
REVOKE ALL ON FUNCTION mission_generic_owner.native_reissue_continuation_v1(uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION mission_generic_owner.native_reissue_continuation_v1(uuid) TO postgres;

installer_source.source:
-- Two current-body deltas+1new owner-only continuation helper; Edge100 and UI unchanged. No table/data/old Fato changes, no provider or budget increase.
BEGIN;SET LOCAL search_path TO pg_catalog,public,extensions;SET LOCAL lock_timeout='5s';SET LOCAL statement_timeout='60s';
DO $usd_install$
DECLARE heads jsonb;actual jsonb;expected jsonb;newpre jsonb;before_extra jsonb;after_extra jsonb;root_text text;root_sha text;n integer;
