 if sig not in root_sigs:
  for key in ['c1266_functions','all_function_headers']:s+=' newpre:=jsonb_set(newpre,'+q('{db_core,'+key+'}')+',(newpre#>'+q('{db_core,'+key+'}')+")||jsonb_build_array(heads));\n"
 s+=" expected:=jsonb_set(expected,'{headers}',(SELECT jsonb_agg(x ORDER BY x->>'signature') FROM (SELECT CASE WHEN h->>'signature'="+q(sig)+" THEN heads ELSE h END x FROM jsonb_array_elements(expected->'headers') h"+(" UNION ALL SELECT heads"if sig not in root_sigs else '')+" ) z));\n"
 if sig in extras:s+=" expected:=jsonb_set(expected,'{legal_dependencies}',(SELECT jsonb_agg(CASE WHEN h->>'signature'="+q(sig)+" THEN heads ELSE h END ORDER BY h->>'signature') FROM jsonb_array_elements(expected->'legal_dependencies') h));\n"
s+=" root_text:=newpre::text;\n"+guard('octet_length(root_text)<=262144','NATIVE_INTENT_ROOT_SIZE')+" root_sha:=encode(extensions.digest(convert_to(root_text,'UTF8'),'sha256'),'hex');\n"
s+=" UPDATE mission_factory_owner.editor_release_readiness SET canonical_preimage=root_text,revision_sha256=root_sha,observed_revision_sha256=root_sha,client_build='mission-factory-admin/2:'||root_sha,updated_at=clock_timestamp() WHERE singleton AND revision_sha256="+q(root)+';\n GET DIAGNOSTICS n=ROW_COUNT;\n'+guard('n=1','NATIVE_INTENT_ROOT_CAS')
